INSERT INTO `new-api`.`logs_tmp_06`(`id`,`user_id`,`created_at`,`type`,`content`,`username`,`token_name`,`model_name`,`quota`,`prompt_tokens`,`completion_tokens`,`use_time`,`is_stream`,`channel_id`,`channel_name`,`token_id`,`group`,`ip`,`request_id`,`other`,`started_at`,`finished_at`,`timeout_cleaned`) VALUES(5541530,3,1782829359,5,'status_code=500, upstream error: do request failed','maas','maas','gpt-image-2-count',0,0,0,3,0,49,NULL,4,'default','','20260630142239962500878268d9d6mGSGRCPT','{\"admin_info\":{\"upstream\":{\"request\":{\"body\":{\"model\":\"gpt-image-2\",\"n\":1,\"prompt\":\"金婚纪念册装饰角花4，四角装饰元素，米黄色，花卉藤蔓，复古边框风格，温馨怀旧，800x800像素\",\"size\":\"1024x1024\"},\"body_truncated\":false,\"headers\":{\"Accept\":\"\",\"Authorization\":\"Bearer sk-xxx\",\"Content-Type\":\"application/json\"},\"method\":\"POST\",\"url\":\"https://ai.yalian.cloud/v1/images/generations\"},\"source\":\"upstream_do_request\"},\"use_channel\":[\"49\",\"49\"]},\"channel_id\":49,\"channel_name\":\"星跃-1000RPM\",\"channel_type\":1,\"error_code\":\"do_request_failed\",\"error_type\":\"new_api_error\",\"request_path\":\"/v1/images/generations\",\"status_code\":500}',1782829359,1782829365,0);
INSERT INTO `new-api`.`logs_tmp_06`(`id`,`user_id`,`created_at`,`type`,`content`,`username`,`token_name`,`model_name`,`quota`,`prompt_tokens`,`completion_tokens`,`use_time`,`is_stream`,`channel_id`,`channel_name`,`token_id`,`group`,`ip`,`request_id`,`other`,`started_at`,`finished_at`,`timeout_cleaned`) VALUES(5541531,3,1782829373,5,'status_code=500, upstream error: do request failed','maas','maas','gpt-image-2',0,0,0,3,0,49,NULL,4,'default','','202606301422532688742978268d9d6w0boPWcM','{\"admin_info\":{\"upstream\":{\"request\":{\"body\":{\"content_type\":\"multipart/form-data\",\"fields\":{\"model\":\"gpt-image-2\",\"prompt\":{\"truncated\":true,\"value\":\"请严格按照以下中文要求，生成 1 张可直接用于中国区游戏商店投放的 16:9 游戏宣传图片。\\n\\n目标场景：16:9 横版游戏宣传图。\\n目标：生成一张兼顾高识别主体特写与标题识别的游戏宣传图。画面需要让标题与主体特写共同构成一个完整、连贯的宣传视觉，让用户优先看清最有识别度的局部主体、关键动作和玩法瞬间，同时通过有设计感的大标题强化品牌识别。标题需要明显突出，但不能遮挡或取代主体特写与关键瞬间。\\n\\n画布：1920x1080，宽高比 16:9。\\n硬性约束：保持构图清晰，并与游戏真实风格一致。\\n\\n游戏信息：\\n- 游戏标题必须显示为「深宫百日录」。\\n- 标题共 5 个字，必须逐字准确，不得替换、改写、缺失、错字、同音字、近义字或其他变体。\\n\\n需要保留的视觉识别：\\n- 画风：国风写实偏Q版。\\n- 情绪氛围：沉稳、宫廷、古韵。\\n\\n参考图要求：\\n- 当前请求附带了开发者提供的参考图，可将其作为玩法内容和视觉方向的补充锚点。\\n- 如果参考图来自实机截图、宣传图或已有素材，应优先提炼其中与真实玩法一致的主体关系、交互对象、行为线索和结果反馈，而不是只提炼表面风格。\\n- 参考图只能帮助校准真实内容、玩法关系和视觉气质，不能把画面带向脱离玩法的概念包装。\\n- 不要直接照搬原图构图、背景、装饰文字、界面排版或 UI。\\n- 若使用实机截图作为参考，只提炼其中最有代表性的玩法符号、环境色调和动作关系，不保留完整截图感和原始布局。\\n- 风格锚定：必须复刻参考图的「保持国风角色立绘的精细度，以及宫廷建筑的细节和整体布局」。背景可简化但需保留宫廷元素，主体（人物或宫殿）细节应丰富，贴近游戏内资产精度。。\\n- 如果参考图带有 HUD、按钮、血条、进度条、数值、角标、卡片、小地图、操作提示或其他游戏内 UI 元素，必须主动忽略并清除；只保留去 UI 后仍然成立的玩法主体和内容关系。\\n- 宣传图只保留纯游戏内容主体、场景关系和美术气质，不保留截图式界面覆盖层，也不要把参考图中的 UI 反馈误当成最终设计元素。\\n\\n差异化方案：\\n- 构图：采用上方标题、下方主体的横向分层构图，避免把参考截图原样铺底。\\n- 主体位置：主体特写集中在中下部，可略微偏左或偏右，让动作方向与标题形成呼应。\\n- 标题位置建议：上方横向标题区。\\n- 标题位于画面上方的稳定横向标题区，整体视觉存在感约占画面 18% 到 24% 左右。\\n- 主体特写与关键瞬间主要落在画面中下方或中部偏下的主体特写区域，与标题位置错开，互不遮挡。\\n\\n场景要求：\\n- 这是一张游戏宣传图，不是纯标题海报，也不是完整截图直接贴字。\\n- 必须保留与游戏一致的核心玩法语义，但不要求把完整玩法流程完整铺开。\\n- 标题文字是重要的宣传识别元素，需要明显突出，但不能压制主体特写与关键瞬间，并应顺着主体动作、场景走势和整体节奏自然融入画面。\\n- 画面使用艺术设计，在保留实机语义的情况下，脱离截图重新编排场景布局，优先选择最有识别度的局部主体与关键玩法瞬间进行艺术重绘和表达，确保角色特征、核心气质、玩家体验与真实游戏一致。\\n- 标题在上方形成品牌锚点，主体特写和关键动作在下方展开，标题顺着场景走势压住画面节奏但不遮挡主体。\\n- 标题放在画面上方的稳定横向标题区，主体特写与关键瞬间放在画面中下方或中部偏下的主体特写区域，两者位置错开，不要互相遮挡，同时要保持构图呼应，不要像后期单独贴上的独立层。\\n- 视觉还原优先级：必须确保生成的画面在美术形式上与参考图高度对齐，严格遵循「保持国风角色立绘的精细度，以及宫廷建筑的细节和整体布局」，并满足「背景可简化但需保留宫廷元素，主体（人物或宫殿）细节应丰富，贴近游戏内资产精度。」，杜绝过度包装导致的货不对板。\\n- 标题需要足够大、足够宽、足够有体积感，成为稳定的品牌识别锚点。\\n- 主体特写与关键瞬间应清晰集中，不要分散成零散背景装饰。\\n- 主特写主体必须优先突出「身着华服、妆容精致的女性角色立绘」，不能退化成抽象题材符号或泛化元素堆砌。\\n- 画面不能只是几个元素散落在背景里，必须围绕「身着华服、妆容精致的女性角色立绘」这个明确主体和一个正在发生的关键瞬间展开，例如「女性角色展示其穿着的华服，或正在进行日常活动」。\\n- 画面需要具有设计感，不能直接照搬原始截图，需要提炼其中最有识别度的局部特征进行艺术加工。\\n- 画面整体应体现“标题显著、主体清楚、瞬间明确、位置清晰、层级明确”，并让标题、主体特写与关键瞬间共同构成完整连贯的视觉整体。\\n- 标题位于画面上方中轴附近，形成明确品牌锚点。\\n- 标题应占据较大宽度和足够厚度，具有明显存在感，但不要覆盖画面中下方或中部偏下的主体特写区域的主体特写。\\n- 画面中下方或中部偏下的主体特写区域必须呈现清晰的局部特写和关键瞬间，让人能一眼看清「身着华服、妆容精致的女性角色立绘」的动作与结果反馈，即「华服展示带来的美观效果，或选择活动后角色属性的变化」，并感知这款游戏的核心玩法语义，即「在深宫中通过日常活动、梳妆打扮和选择寝宫，体验古代宫廷生活、角色养成和剧情互动。」。\\n- 画面可围绕 角色装扮、宫殿选择与管理、日程活动安排、属性养成 中的少量关键元素展开，但必须突出一个主主体，不要把整体玩法平均铺满。\\n- 除主主体外，只可保留少量能支撑瞬间成立的次要主体，例如 俯视视角的宫殿地图、宫殿建筑群落、日程活动列表，不要把所有主体平均陈列。\\n- 标题不要遮挡主体动作与结果反馈。\\n- 画面中应保留少量最具代表性的局部元素，但必须经过整理，避免杂乱。\\n- 必须保留「在深宫中通过日常活动、梳妆打扮和选择寝宫，体验古代宫廷生活、角色养成和剧情互动。」这一核心玩法语义，但不要求把整套玩法链路完整铺开。\\n- 可以保留 角色装扮、宫殿选择与管理、日程活动安排、属性养成 等核心元素，但应优先服务于主体特写和关键瞬间，避免平均散落。\\n- 重点表现「宫廷养成模拟器」，并通过局部特写、动作爆发和结果反馈去传达 古代宫廷生活与女性角色养成 与 模拟经营 的结合关系。\\n- 标题「深宫百日录」需要有明确的艺术化设计，字形、材质、轮廓、描边、光效或装饰细节应与游戏气质一致，并与主体特写、动作氛围和场景气质自然呼应，但必须保持清晰可读。\\n- 标题应具有 端庄、古典、奢华，可以带有 烫金或描边文字、搭配中国传统纹样或元素 或 字体具有书法或篆刻韵味，但不要脱离参考图整体风格。\\n- 如果游戏本身画面较粗糙、玩法元素较简单，可以适度进行宣传图式提炼和强化，但这种强化应体现在线条的精致度和色彩的通透感上，不能脱离真实游戏的气质。\\n- 若背景来自实机内容，可适当进行弱化、简化和整理，例如压暗、降对比、降饱和、柔化、减少杂讯，让标题和主体特写都更清楚。\\n- 背景和场景元素只能辅助说明游戏内容，不能喧宾夺主，也不能弱到只剩空背景。背景应保持克制，严禁添加实机不符的内容画面。\\n\\n文字要求：\\n- 画面中除游戏标题外，不要出现其他任何文字、按钮文案、说明文案、宣传\"},\"quality\":\"medium\",\"size\":\"1536x1024\"},\"files\":[{\"content_type\":\"image/png\",\"field\":\"image[]\",\"filename\":\"image_0.png\",\"size\":200930,\"truncated\":false},{\"content_type\":\"image/png\",\"field\":\"image[]\",\"filename\":\"image_1.png\",\"size\":1025906,\"truncated\":false},{\"content_type\":\"image/png\",\"field\":\"image[]\",\"filename\":\"image_2.png\",\"size\":376872,\"truncated\":false}]},\"body_truncated\":false,\"headers\":{\"Accept\":\"\",\"Authorization\":\"Bearer sk-xxx\",\"Content-Type\":\"multipart/form-data; boundary=27fb47656e1fa070b9f02b4751701fb629f6b7dbfea4255da444dfc591a6\"},\"method\":\"POST\",\"url\":\"https://ai.yalian.cloud/v1/images/edits\"},\"source\":\"upstream_do_request\"},\"use_channel\":[\"49\"]},\"channel_id\":49,\"channel_name\":\"星跃-1000RPM\",\"channel_type\":1,\"error_code\":\"do_request_failed\",\"error_type\":\"new_api_error\",\"request_path\":\"/v1/images/edits\",\"status_code\":500}',1782829373,1782829376,0);
INSERT INTO `new-api`.`logs_tmp_06`(`id`,`user_id`,`created_at`,`type`,`content`,`username`,`token_name`,`model_name`,`quota`,`prompt_tokens`,`completion_tokens`,`use_time`,`is_stream`,`channel_id`,`channel_name`,`token_id`,`group`,`ip`,`request_id`,`other`,`started_at`,`finished_at`,`timeout_cleaned`) VALUES(5541532,3,1782829373,5,'status_code=500, upstream error: do request failed','maas','maas','gpt-image-2',0,0,0,3,0,49,NULL,4,'default','','202606301422532688742978268d9d6w0boPWcM','{\"admin_info\":{\"upstream\":{\"request\":{\"body\":{\"content_type\":\"multipart/form-data\",\"fields\":{\"model\":\"gpt-image-2\",\"prompt\":{\"truncated\":true,\"value\":\"请严格按照以下中文要求，生成 1 张可直接用于中国区游戏商店投放的 16:9 游戏宣传图片。\\n\\n目标场景：16:9 横版游戏宣传图。\\n目标：生成一张兼顾高识别主体特写与标题识别的游戏宣传图。画面需要让标题与主体特写共同构成一个完整、连贯的宣传视觉，让用户优先看清最有识别度的局部主体、关键动作和玩法瞬间，同时通过有设计感的大标题强化品牌识别。标题需要明显突出，但不能遮挡或取代主体特写与关键瞬间。\\n\\n画布：1920x1080，宽高比 16:9。\\n硬性约束：保持构图清晰，并与游戏真实风格一致。\\n\\n游戏信息：\\n- 游戏标题必须显示为「深宫百日录」。\\n- 标题共 5 个字，必须逐字准确，不得替换、改写、缺失、错字、同音字、近义字或其他变体。\\n\\n需要保留的视觉识别：\\n- 画风：国风写实偏Q版。\\n- 情绪氛围：沉稳、宫廷、古韵。\\n\\n参考图要求：\\n- 当前请求附带了开发者提供的参考图，可将其作为玩法内容和视觉方向的补充锚点。\\n- 如果参考图来自实机截图、宣传图或已有素材，应优先提炼其中与真实玩法一致的主体关系、交互对象、行为线索和结果反馈，而不是只提炼表面风格。\\n- 参考图只能帮助校准真实内容、玩法关系和视觉气质，不能把画面带向脱离玩法的概念包装。\\n- 不要直接照搬原图构图、背景、装饰文字、界面排版或 UI。\\n- 若使用实机截图作为参考，只提炼其中最有代表性的玩法符号、环境色调和动作关系，不保留完整截图感和原始布局。\\n- 风格锚定：必须复刻参考图的「保持国风角色立绘的精细度，以及宫廷建筑的细节和整体布局」。背景可简化但需保留宫廷元素，主体（人物或宫殿）细节应丰富，贴近游戏内资产精度。。\\n- 如果参考图带有 HUD、按钮、血条、进度条、数值、角标、卡片、小地图、操作提示或其他游戏内 UI 元素，必须主动忽略并清除；只保留去 UI 后仍然成立的玩法主体和内容关系。\\n- 宣传图只保留纯游戏内容主体、场景关系和美术气质，不保留截图式界面覆盖层，也不要把参考图中的 UI 反馈误当成最终设计元素。\\n\\n差异化方案：\\n- 构图：采用上方标题、下方主体的横向分层构图，避免把参考截图原样铺底。\\n- 主体位置：主体特写集中在中下部，可略微偏左或偏右，让动作方向与标题形成呼应。\\n- 标题位置建议：上方横向标题区。\\n- 标题位于画面上方的稳定横向标题区，整体视觉存在感约占画面 18% 到 24% 左右。\\n- 主体特写与关键瞬间主要落在画面中下方或中部偏下的主体特写区域，与标题位置错开，互不遮挡。\\n\\n场景要求：\\n- 这是一张游戏宣传图，不是纯标题海报，也不是完整截图直接贴字。\\n- 必须保留与游戏一致的核心玩法语义，但不要求把完整玩法流程完整铺开。\\n- 标题文字是重要的宣传识别元素，需要明显突出，但不能压制主体特写与关键瞬间，并应顺着主体动作、场景走势和整体节奏自然融入画面。\\n- 画面使用艺术设计，在保留实机语义的情况下，脱离截图重新编排场景布局，优先选择最有识别度的局部主体与关键玩法瞬间进行艺术重绘和表达，确保角色特征、核心气质、玩家体验与真实游戏一致。\\n- 标题在上方形成品牌锚点，主体特写和关键动作在下方展开，标题顺着场景走势压住画面节奏但不遮挡主体。\\n- 标题放在画面上方的稳定横向标题区，主体特写与关键瞬间放在画面中下方或中部偏下的主体特写区域，两者位置错开，不要互相遮挡，同时要保持构图呼应，不要像后期单独贴上的独立层。\\n- 视觉还原优先级：必须确保生成的画面在美术形式上与参考图高度对齐，严格遵循「保持国风角色立绘的精细度，以及宫廷建筑的细节和整体布局」，并满足「背景可简化但需保留宫廷元素，主体（人物或宫殿）细节应丰富，贴近游戏内资产精度。」，杜绝过度包装导致的货不对板。\\n- 标题需要足够大、足够宽、足够有体积感，成为稳定的品牌识别锚点。\\n- 主体特写与关键瞬间应清晰集中，不要分散成零散背景装饰。\\n- 主特写主体必须优先突出「身着华服、妆容精致的女性角色立绘」，不能退化成抽象题材符号或泛化元素堆砌。\\n- 画面不能只是几个元素散落在背景里，必须围绕「身着华服、妆容精致的女性角色立绘」这个明确主体和一个正在发生的关键瞬间展开，例如「女性角色展示其穿着的华服，或正在进行日常活动」。\\n- 画面需要具有设计感，不能直接照搬原始截图，需要提炼其中最有识别度的局部特征进行艺术加工。\\n- 画面整体应体现“标题显著、主体清楚、瞬间明确、位置清晰、层级明确”，并让标题、主体特写与关键瞬间共同构成完整连贯的视觉整体。\\n- 标题位于画面上方中轴附近，形成明确品牌锚点。\\n- 标题应占据较大宽度和足够厚度，具有明显存在感，但不要覆盖画面中下方或中部偏下的主体特写区域的主体特写。\\n- 画面中下方或中部偏下的主体特写区域必须呈现清晰的局部特写和关键瞬间，让人能一眼看清「身着华服、妆容精致的女性角色立绘」的动作与结果反馈，即「华服展示带来的美观效果，或选择活动后角色属性的变化」，并感知这款游戏的核心玩法语义，即「在深宫中通过日常活动、梳妆打扮和选择寝宫，体验古代宫廷生活、角色养成和剧情互动。」。\\n- 画面可围绕 角色装扮、宫殿选择与管理、日程活动安排、属性养成 中的少量关键元素展开，但必须突出一个主主体，不要把整体玩法平均铺满。\\n- 除主主体外，只可保留少量能支撑瞬间成立的次要主体，例如 俯视视角的宫殿地图、宫殿建筑群落、日程活动列表，不要把所有主体平均陈列。\\n- 标题不要遮挡主体动作与结果反馈。\\n- 画面中应保留少量最具代表性的局部元素，但必须经过整理，避免杂乱。\\n- 必须保留「在深宫中通过日常活动、梳妆打扮和选择寝宫，体验古代宫廷生活、角色养成和剧情互动。」这一核心玩法语义，但不要求把整套玩法链路完整铺开。\\n- 可以保留 角色装扮、宫殿选择与管理、日程活动安排、属性养成 等核心元素，但应优先服务于主体特写和关键瞬间，避免平均散落。\\n- 重点表现「宫廷养成模拟器」，并通过局部特写、动作爆发和结果反馈去传达 古代宫廷生活与女性角色养成 与 模拟经营 的结合关系。\\n- 标题「深宫百日录」需要有明确的艺术化设计，字形、材质、轮廓、描边、光效或装饰细节应与游戏气质一致，并与主体特写、动作氛围和场景气质自然呼应，但必须保持清晰可读。\\n- 标题应具有 端庄、古典、奢华，可以带有 烫金或描边文字、搭配中国传统纹样或元素 或 字体具有书法或篆刻韵味，但不要脱离参考图整体风格。\\n- 如果游戏本身画面较粗糙、玩法元素较简单，可以适度进行宣传图式提炼和强化，但这种强化应体现在线条的精致度和色彩的通透感上，不能脱离真实游戏的气质。\\n- 若背景来自实机内容，可适当进行弱化、简化和整理，例如压暗、降对比、降饱和、柔化、减少杂讯，让标题和主体特写都更清楚。\\n- 背景和场景元素只能辅助说明游戏内容，不能喧宾夺主，也不能弱到只剩空背景。背景应保持克制，严禁添加实机不符的内容画面。\\n\\n文字要求：\\n- 画面中除游戏标题外，不要出现其他任何文字、按钮文案、说明文案、宣传\"},\"quality\":\"medium\",\"size\":\"1536x1024\"},\"files\":[{\"content_type\":\"image/png\",\"field\":\"image[]\",\"filename\":\"image_0.png\",\"size\":200930,\"truncated\":false},{\"content_type\":\"image/png\",\"field\":\"image[]\",\"filename\":\"image_1.png\",\"size\":1025906,\"truncated\":false},{\"content_type\":\"image/png\",\"field\":\"image[]\",\"filename\":\"image_2.png\",\"size\":376872,\"truncated\":false}]},\"body_truncated\":false,\"headers\":{\"Accept\":\"\",\"Authorization\":\"Bearer sk-xxx\",\"Content-Type\":\"multipart/form-data; boundary=18e02e32294bf0be20ce45dcdf8664f156cb58075c03671dbb39b6aac5f8\"},\"method\":\"POST\",\"url\":\"https://ai.yalian.cloud/v1/images/edits\"},\"source\":\"upstream_do_request\"},\"use_channel\":[\"49\",\"49\"]},\"channel_id\":49,\"channel_name\":\"星跃-1000RPM\",\"channel_type\":1,\"error_code\":\"do_request_failed\",\"error_type\":\"new_api_error\",\"request_path\":\"/v1/images/edits\",\"status_code\":500}',1782829373,1782829379,0);
INSERT INTO `new-api`.`logs_tmp_06`(`id`,`user_id`,`created_at`,`type`,`content`,`username`,`token_name`,`model_name`,`quota`,`prompt_tokens`,`completion_tokens`,`use_time`,`is_stream`,`channel_id`,`channel_name`,`token_id`,`group`,`ip`,`request_id`,`other`,`started_at`,`finished_at`,`timeout_cleaned`) VALUES(5541533,3,1782829395,5,'status_code=500, upstream error: do request failed','maas','maas','gpt-image-2-count',0,0,0,3,0,49,NULL,4,'default','','202606301423157458982968268d9d6bfAViZ43','{\"admin_info\":{\"upstream\":{\"request\":{\"body\":{\"model\":\"gpt-image-2\",\"n\":1,\"prompt\":\"Aerial drone view of a modern agricultural industrial park, wide landscape composition. Multiple large white-greenhouse structures arranged in neat rows, surrounded by organized crop fields with geometric patterns of green vegetation. Professional commercial photography style, low saturation, muted deep green and warm golden tones, overcast soft lighting for a calm business atmosphere. No text, no watermark, no people. The scene conveys modern sustainable agriculture and professionalism. Deep green (#1a3c2a) and warm sand gold (#c49a3c) color palette, editorial quality.\",\"size\":\"1536x1024\"},\"body_truncated\":false,\"headers\":{\"Accept\":\"\",\"Authorization\":\"Bearer sk-xxx\",\"Content-Type\":\"application/json\"},\"method\":\"POST\",\"url\":\"https://ai.yalian.cloud/v1/images/generations\"},\"source\":\"upstream_do_request\"},\"use_channel\":[\"49\"]},\"channel_id\":49,\"channel_name\":\"星跃-1000RPM\",\"channel_type\":1,\"error_code\":\"do_request_failed\",\"error_type\":\"new_api_error\",\"request_path\":\"/v1/images/generations\",\"status_code\":500}',1782829395,1782829398,0);
INSERT INTO `new-api`.`logs_tmp_06`(`id`,`user_id`,`created_at`,`type`,`content`,`username`,`token_name`,`model_name`,`quota`,`prompt_tokens`,`completion_tokens`,`use_time`,`is_stream`,`channel_id`,`channel_name`,`token_id`,`group`,`ip`,`request_id`,`other`,`started_at`,`finished_at`,`timeout_cleaned`) VALUES(5541534,3,1782829395,5,'status_code=500, upstream error: do request failed','maas','maas','gpt-image-2-count',0,0,0,3,0,49,NULL,4,'default','','202606301423157458982968268d9d6bfAViZ43','{\"admin_info\":{\"upstream\":{\"request\":{\"body\":{\"model\":\"gpt-image-2\",\"n\":1,\"prompt\":\"Aerial drone view of a modern agricultural industrial park, wide landscape composition. Multiple large white-greenhouse structures arranged in neat rows, surrounded by organized crop fields with geometric patterns of green vegetation. Professional commercial photography style, low saturation, muted deep green and warm golden tones, overcast soft lighting for a calm business atmosphere. No text, no watermark, no people. The scene conveys modern sustainable agriculture and professionalism. Deep green (#1a3c2a) and warm sand gold (#c49a3c) color palette, editorial quality.\",\"size\":\"1536x1024\"},\"body_truncated\":false,\"headers\":{\"Accept\":\"\",\"Authorization\":\"Bearer sk-xxx\",\"Content-Type\":\"application/json\"},\"method\":\"POST\",\"url\":\"https://ai.yalian.cloud/v1/images/generations\"},\"source\":\"upstream_do_request\"},\"use_channel\":[\"49\",\"49\"]},\"channel_id\":49,\"channel_name\":\"星跃-1000RPM\",\"channel_type\":1,\"error_code\":\"do_request_failed\",\"error_type\":\"new_api_error\",\"request_path\":\"/v1/images/generations\",\"status_code\":500}',1782829395,1782829402,0);
INSERT INTO `new-api`.`logs_tmp_06`(`id`,`user_id`,`created_at`,`type`,`content`,`username`,`token_name`,`model_name`,`quota`,`prompt_tokens`,`completion_tokens`,`use_time`,`is_stream`,`channel_id`,`channel_name`,`token_id`,`group`,`ip`,`request_id`,`other`,`started_at`,`finished_at`,`timeout_cleaned`) VALUES(5541566,3,1782830159,5,'status_code=500, upstream error: do request failed','maas','maas','gpt-image-2',0,0,0,3,0,49,NULL,4,'default','','202606301435593305927548268d9d6D5TyUczu','{\"admin_info\":{\"upstream\":{\"request\":{\"body\":{\"content_type\":\"multipart/form-data\",\"fields\":{\"model\":\"gpt-image-2\",\"prompt\":\"根据两张参考图的装饰插画风格，生成一张横版16:9魔法酒馆游戏背景图。重点要求：不要写实感，不要摄影感，不要厚重油画感，不要皱巴巴的布料和脏乱纹理，不要过多真实阴影。画面要是干净、平面、装饰性强、图形化的童话绘本游戏背景。\\n\\n主题：魔法酒馆室内。中央是清晰的装饰拱门和吧台，左右有拱窗、圆桌、酒桶、吊灯、挂毯、帷幔、彩色玻璃、魔法光点、金线边框。物体都要被简化成优雅的大色块和明确轮廓，线条细致清晰，边缘干净。整体像参考图那样有舞台布景感、剪纸拼贴感、装饰海报感，而不是真实3D室内。\\n\\n视觉风格：平面插画，清楚线稿，装饰性轮廓，几何图案，高级金箔点缀，星月符号，菱形花纹，优雅曲线，分区色块。减少复杂材质噪声；木头、石墙、布料只用简洁图形纹理表现，不能有皱皱的真实褶皱。帷幔要像参考图中优雅的大弧形装饰布片，平整、图形化、有金线花纹。\\n\\n色彩：丰富但干净。主色为孔雀绿、湖蓝、靛蓝、紫罗兰、酒红、玫瑰红、暖金、象牙白。颜色分区明确，明度比上一版更通透，不能黑。暖金灯光以平面光晕和金色线条表现，冷蓝窗光以干净渐变色块表现。\\n\\n构图：中轴对称，舞台式酒馆大厅，前景桌椅简化成装饰性轮廓，中景吧台和酒柜清晰，背景拱窗和夜空清楚。装饰密度高，但每个元素边界清楚，不能糊，不能皱，不能写实。不要人物，不要文字，不要水印。\",\"quality\":\"medium\",\"size\":\"1536x1024\"},\"files\":[{\"content_type\":\"image/jpeg\",\"field\":\"image[]\",\"filename\":\"image_0.jpeg\",\"size\":440250,\"truncated\":false},{\"content_type\":\"image/jpeg\",\"field\":\"image[]\",\"filename\":\"image_1.jpeg\",\"size\":458028,\"truncated\":false}]},\"body_truncated\":false,\"headers\":{\"Accept\":\"\",\"Authorization\":\"Bearer sk-xxx\",\"Content-Type\":\"multipart/form-data; boundary=9f74e1160d94fb99159211542ed071b46918a7872f526b2b86ba679fe236\"},\"method\":\"POST\",\"url\":\"https://ai.yalian.cloud/v1/images/edits\"},\"source\":\"upstream_do_request\"},\"use_channel\":[\"49\"]},\"channel_id\":49,\"channel_name\":\"星跃-1000RPM\",\"channel_type\":1,\"error_code\":\"do_request_failed\",\"error_type\":\"new_api_error\",\"request_path\":\"/v1/images/edits\",\"status_code\":500}',1782830159,1782830163,0);
