INSERT INTO `new-api`.`logs_tmp_06`(`id`,`user_id`,`created_at`,`type`,`content`,`username`,`token_name`,`model_name`,`quota`,`prompt_tokens`,`completion_tokens`,`use_time`,`is_stream`,`channel_id`,`channel_name`,`token_id`,`group`,`ip`,`request_id`,`other`,`started_at`,`finished_at`,`timeout_cleaned`) VALUES(5541700,3,1782832857,5,'status_code=500, upstream error: do request failed','maas','maas','gpt-image-2',0,0,0,3,0,49,NULL,4,'default','','202606301520576168106148268d9d6QOP2vsd8','{\"admin_info\":{\"upstream\":{\"request\":{\"body\":{\"model\":\"gpt-image-2\",\"n\":1,\"prompt\":\"赛璐璐平涂，色块边界清晰，细线深棕描边，阴影仅一层浅色块，配色柔和通透；Q版古风宣花斧，正面微微倾斜视角，斧头半月形亮铜色（#C0A060），斧面刻花卉纹，斧柄红木色，斧尾有小铁环；独立道具，无地面底座，无投影，无背景，纯色透明背景，可单独抠图使用；调色板参照（主草#D0E8C8，阴影灰绿#C8D098，次级柔绿#B0D0A0，泥土#C0A888，道路高光#E0D8B8，灰青#C0D8B0，石#707050，暗灰#808060，木棕#605840，深描边#302020，辅描边#383030，丹药红#C06040，丹药金#D4B060，灵液青#70B0A0，朱砂红#C04030，墨色#3A3030，符纸黄#E8D890，暖玉白#E8E0D0，紫晶#9070B0，寒铁蓝#6088A0，青铜绿#709070，琥珀橙#D09050）；不要地块，不要地面，不要草地背景，不要山体，不要水体，不要复杂场景，不要模型感，不要微缩沙盘，不要玩具质感，不要塑料质感，不要强烈高光，不要厚重3D渲染，不要浮空岛，不要厚底座，不要岩石断面，不要多层台地；禁止高饱和霓虹色、大面积纯黑、强反光白色、金属高光、塑料高光；禁止投影、禁止阴影、禁止地面网格；禁止3D立体感、禁止写实照片风；白底透明背景，道具居中，边缘轮廓清楚，512×512。\",\"quality\":\"medium\",\"size\":\"1024x1024\"},\"body_truncated\":false,\"headers\":{\"Accept\":\"\",\"Authorization\":\"Bearer sk-xxx\",\"Content-Type\":\"application/json\"},\"method\":\"POST\",\"url\":\"https://ai.yalian.cloud/v1/images/generations\"},\"source\":\"upstream_do_request\"},\"use_channel\":[\"49\"]},\"channel_id\":49,\"channel_name\":\"星跃-1000RPM\",\"channel_type\":1,\"error_code\":\"do_request_failed\",\"error_type\":\"new_api_error\",\"request_path\":\"/v1/images/generations\",\"status_code\":500}',1782832857,1782832861,0);
