INSERT INTO `new-api`.`logs_tmp_06`(`id`,`user_id`,`created_at`,`type`,`content`,`username`,`token_name`,`model_name`,`quota`,`prompt_tokens`,`completion_tokens`,`use_time`,`is_stream`,`channel_id`,`channel_name`,`token_id`,`group`,`ip`,`request_id`,`other`,`started_at`,`finished_at`,`timeout_cleaned`) VALUES(5541824,3,1782834987,5,'status_code=500, upstream error: do request failed','maas','maas','gpt-image-2',0,0,0,3,0,49,NULL,4,'default','','202606301556274222126678268d9d6Lf5UFhHr','{\"admin_info\":{\"upstream\":{\"request\":{\"body\":{\"model\":\"gpt-image-2\",\"n\":1,\"prompt\":\"你是顶级视觉创意设计师。\\n\\n任务：根据指定页型的单页内容，直接生成 1 张 16:9 横版中文视觉画面。\\n\\n目标页型：\\nG6-01 - 标题页/封面（多风格）\\noutline_rules:\\n- 强化封面气质与主题建立\\n- 减少复杂信息拆解，适合开场和视觉引入\\n- 优先形成有冲击力的标题页与配套章节页\\ndesign_rules:\\n- 主视觉优先\\n- 标题层级鲜明\\n- 装饰元素可稍强，但不能破坏阅读\\n\\n要求：\\n1. 这是单张完成度很高的 16:9 横版中文视觉成品图，不是线框图，不是软件界面截图。\\n2. 允许你自由发挥画面的风格、构图、材质、色彩、图文关系和视觉焦点，不要受模板化商务页面约束。\\n3. 不要显式模仿 PPT、幻灯片、投影幕布、演示文稿截图或办公排版风格。\\n4. 画面优先追求美观、艺术感、设计完成度和视觉记忆点。\\n5. 文本可以压缩成短句展示，但必须保留页面核心信息和内容层级。\\n6. 保留标题、正文、关键数字、图表或结构信息的基本可识别性，但不要求规整保守。\\n7. 优先避免机械对称、平均分布、模板感强的默认解；鼓励非对称构图、强主次、留白节奏、块面对比和大胆重心。\\n8. 主视觉中心可以来自图形、图片区、关键数字、块面关系或标题，但不要自动收敛到单一安全解。\\n9. 避免水印、UI 按钮、浏览器边框、设备边框、相框、品牌 Logo 和无关人物。\\n10. 只要核心信息仍可识别，就优先选择更有感染力、更有艺术表达的视觉方案。\\n\\n单页内容信息：\\n{\\n  \\\"page_category_code\\\": \\\"G6-01\\\",\\n  \\\"title\\\": \\\"极致服务构建核心竞争力\\\",\\n  \\\"subtitle\\\": \\\"海底捞“魔鬼服务”与员工激励机制解析\\\",\\n  \\\"page_goal\\\": \\\"建立封面强有力的视觉主题，抛出海底捞极致服务与核心竞争力的话题，吸引受众注意力。\\\",\\n  \\\"narrative\\\": \\\"在同质化竞争激烈的餐饮行业，海底捞凭借超预期的情感体验与细节关怀，成功将“微笑服务”转化为品牌最强大的护城河。\\\",\\n  \\\"bullets\\\": [],\\n  \\\"source_evidence\\\": [\\n    \\\"海底捞以极致服务构建核心竞争力及员工激励措施分析\\\",\\n    \\\"海底捞的核心竞争力并非菜品味道，而是极致的“魔鬼服务”\\\",\\n    \\\"让客户感受到了“超预期”服务\\\",\\n    \\\"让员工自发地去提供微笑服务\\\"\\n  ]\\n}\",\"quality\":\"high\",\"size\":\"2048x1152\"},\"body_truncated\":false,\"headers\":{\"Accept\":\"\",\"Authorization\":\"Bearer sk-xxx\",\"Content-Type\":\"application/json\"},\"method\":\"POST\",\"url\":\"https://ai.yalian.cloud/v1/images/generations\"},\"source\":\"upstream_do_request\"},\"use_channel\":[\"49\"]},\"channel_id\":49,\"channel_name\":\"星跃-1000RPM\",\"channel_type\":1,\"error_code\":\"do_request_failed\",\"error_type\":\"new_api_error\",\"request_path\":\"/v1/images/generations\",\"status_code\":500}',1782834987,1782834990,0);
