INSERT INTO `new-api`.`logs_tmp_06`(`id`,`user_id`,`created_at`,`type`,`content`,`username`,`token_name`,`model_name`,`quota`,`prompt_tokens`,`completion_tokens`,`use_time`,`is_stream`,`channel_id`,`channel_name`,`token_id`,`group`,`ip`,`request_id`,`other`,`started_at`,`finished_at`,`timeout_cleaned`) VALUES(5541829,3,1782835279,5,'status_code=500, upstream error: do request failed','maas','maas','gpt-image-2',0,0,0,3,0,49,NULL,4,'default','','20260630160119906286038268d9d6l7CeBhsl','{\"admin_info\":{\"upstream\":{\"request\":{\"body\":{\"content_type\":\"multipart/form-data\",\"fields\":{\"model\":\"gpt-image-2\",\"prompt\":\"请对原图进行编辑。编辑指令：基于原图重新生成同一个原创8bit像素风平台跳跃工人角色。保留原图的整体比例、圆顶短帽檐工人帽、深紫色帽子、橙黄色上衣、青绿色工装裤方向、米白色手套、深棕色鞋子和站姿。必须把背景改成纯绿色绿幕，背景颜色严格为#00FF00，不能有黑色、渐变、透明或杂色。重画脸部，让脸部更清晰可爱：两只分明的大眼睛、清楚圆鼻子、友好微笑、清楚胡须，五官不能糊成一团。重画工装背带裤细节：必须完整显示两条肩带、胸前工装片、胸前口袋、裤腿、裤脚和纽扣，背带裤不能缺失或只画半截。保持原创设计，不要字母、徽章、圆形标志，不要红帽蓝裤经典配色，不要版权角色原版脸型。硬边8bit低色数像素风，清晰黑色像素描边，适合作为32x64动作精灵图参考。\",\"quality\":\"medium\",\"size\":\"1024x1536\"},\"files\":[{\"content_type\":\"image/png\",\"field\":\"image\",\"filename\":\"image_0.png\",\"size\":145194,\"truncated\":false}]},\"body_truncated\":false,\"headers\":{\"Accept\":\"\",\"Authorization\":\"Bearer sk-xxx\",\"Content-Type\":\"multipart/form-data; boundary=23bfaf0a2e36c4fe1e4beb5ca439ef3633ebf98739d489448b90bb0d25b7\"},\"method\":\"POST\",\"url\":\"https://ai.yalian.cloud/v1/images/edits\"},\"source\":\"upstream_do_request\"},\"use_channel\":[\"49\",\"49\"]},\"channel_id\":49,\"channel_name\":\"星跃-1000RPM\",\"channel_type\":1,\"error_code\":\"do_request_failed\",\"error_type\":\"new_api_error\",\"request_path\":\"/v1/images/edits\",\"status_code\":500}',1782835279,1782835286,0);
