INSERT INTO `new-api`.`logs_tmp_06`(`id`,`user_id`,`created_at`,`type`,`content`,`username`,`token_name`,`model_name`,`quota`,`prompt_tokens`,`completion_tokens`,`use_time`,`is_stream`,`channel_id`,`channel_name`,`token_id`,`group`,`ip`,`request_id`,`other`,`started_at`,`finished_at`,`timeout_cleaned`) VALUES(5542034,3,1782838494,5,'status_code=500, upstream error: do request failed','maas','maas','gpt-image-2',0,0,0,3,0,49,NULL,4,'default','','202606301654547219917498268d9d6HKDyZLO8','{\"admin_info\":{\"upstream\":{\"request\":{\"body\":{\"model\":\"gpt-image-2\",\"n\":1,\"prompt\":\"赛璐璐平涂，色块边界清晰，细线深棕描边，阴影仅一层浅色块，配色柔和通透；Q版古风梅花石，正面略微俯视视角，一块灰白色石头（#D0C8B0），表面有粉红色梅花状斑纹；独立道具，无地面底座，无投影，无背景，纯色透明背景，可单独抠图使用；不要地面、背景、模型感、强烈高光、厚重3D渲染；禁止投影、阴影、3D立体感、写实照片风；白底透明背景，道具居中，边缘轮廓清楚，512×512。\",\"quality\":\"medium\",\"size\":\"1024x1024\"},\"body_truncated\":false,\"headers\":{\"Accept\":\"\",\"Authorization\":\"Bearer sk-xxx\",\"Content-Type\":\"application/json\"},\"method\":\"POST\",\"url\":\"https://ai.yalian.cloud/v1/images/generations\"},\"source\":\"upstream_do_request\"},\"use_channel\":[\"49\",\"49\"]},\"channel_id\":49,\"channel_name\":\"星跃-1000RPM\",\"channel_type\":1,\"error_code\":\"do_request_failed\",\"error_type\":\"new_api_error\",\"request_path\":\"/v1/images/generations\",\"status_code\":500}',1782838494,1782838501,0);
INSERT INTO `new-api`.`logs_tmp_06`(`id`,`user_id`,`created_at`,`type`,`content`,`username`,`token_name`,`model_name`,`quota`,`prompt_tokens`,`completion_tokens`,`use_time`,`is_stream`,`channel_id`,`channel_name`,`token_id`,`group`,`ip`,`request_id`,`other`,`started_at`,`finished_at`,`timeout_cleaned`) VALUES(5542036,3,1782838559,5,'status_code=500, upstream error: do request failed','maas','maas','gpt-image-2',0,0,0,3,0,49,NULL,4,'default','','202606301655591690282748268d9d6TpzSXrvV','{\"admin_info\":{\"upstream\":{\"request\":{\"body\":{\"content_type\":\"multipart/form-data\",\"fields\":{\"model\":\"gpt-image-2\",\"prompt\":{\"truncated\":true,\"value\":\"请严格按照以下中文要求，生成 1 张可直接用于中国区游戏商店投放的 16:9 游戏宣传图片。\\n\\n目标场景：16:9 横版游戏宣传图。\\n目标：生成一张兼顾高识别主体特写与标题识别的游戏宣传图。画面需要让标题与主体特写共同构成一个完整、连贯的宣传视觉，让用户优先看清最有识别度的局部主体、关键动作和玩法瞬间，同时通过有设计感的大标题强化品牌识别。标题需要明显突出，但不能遮挡或取代主体特写与关键瞬间。\\n\\n画布：1920x1080，宽高比 16:9。\\n硬性约束：保持构图清晰，并与游戏真实风格一致。\\n\\n游戏信息：\\n- 游戏标题必须显示为「弹弹世界杯：足球全明星」。\\n- 标题共 11 个字，必须逐字准确，不得替换、改写、缺失、错字、同音字、近义字或其他变体。\\n\\n需要保留的视觉识别：\\n- 画风：卡通扁平风格。\\n- 情绪氛围：轻松活泼。\\n\\n参考图要求：\\n- 当前请求附带了开发者提供的参考图，可将其作为玩法内容和视觉方向的补充锚点。\\n- 如果参考图来自实机截图、宣传图或已有素材，应优先提炼其中与真实玩法一致的主体关系、交互对象、行为线索和结果反馈，而不是只提炼表面风格。\\n- 参考图只能帮助校准真实内容、玩法关系和视觉气质，不能把画面带向脱离玩法的概念包装。\\n- 不要直接照搬原图构图、背景、装饰文字、界面排版或 UI。\\n- 若使用实机截图作为参考，只提炼其中最有代表性的玩法符号、环境色调和动作关系，不保留完整截图感和原始布局。\\n- 风格锚定：必须复刻参考图的「保持鲜明的卡通Q版人物和扁平化场景」。背景简洁，突出角色和关键玩法元素，细节密度适中，不宜过于写实或复杂。\\n- 如果参考图带有 HUD、按钮、血条、进度条、数值、角标、卡片、小地图、操作提示或其他游戏内 UI 元素，必须主动忽略并清除；只保留去 UI 后仍然成立的玩法主体和内容关系。\\n- 宣传图只保留纯游戏内容主体、场景关系和美术气质，不保留截图式界面覆盖层，也不要把参考图中的 UI 反馈误当成最终设计元素。\\n\\n差异化方案：\\n- 构图：采用上方主体、下方标题的层次构图，让主体先被看清，再由下方标题完成品牌识别。\\n- 主体位置：主体特写集中在中上方，关键反馈避开下方标题区，避免标题覆盖玩法信息。\\n- 标题位置建议：下方横向标题区。\\n- 标题位于画面下方的稳定横向标题区，整体视觉存在感约占画面 16% 到 22% 左右。\\n- 主体特写与关键瞬间主要落在画面中上方或中部偏上的主体特写区域，与标题位置错开，互不遮挡。\\n\\n场景要求：\\n- 这是一张游戏宣传图，不是纯标题海报，也不是完整截图直接贴字。\\n- 必须保留与游戏一致的核心玩法语义，但不要求把完整玩法流程完整铺开。\\n- 标题文字是重要的宣传识别元素，需要明显突出，但不能压制主体特写与关键瞬间，并应顺着主体动作、场景走势和整体节奏自然融入画面。\\n- 画面使用艺术设计，在保留实机语义的情况下，脱离截图重新编排场景布局，优先选择最有识别度的局部主体与关键玩法瞬间进行艺术重绘和表达，确保角色特征、核心气质、玩家体验与真实游戏一致。\\n- 标题在下方托住画面，主体特写和关键动作在上方展开，标题像场景的一部分而不是后期贴字。\\n- 标题放在画面下方的稳定横向标题区，主体特写与关键瞬间放在画面中上方或中部偏上的主体特写区域，两者位置错开，不要互相遮挡，同时要保持构图呼应，不要像后期单独贴上的独立层。\\n- 视觉还原优先级：必须确保生成的画面在美术形式上与参考图高度对齐，严格遵循「保持鲜明的卡通Q版人物和扁平化场景」，并满足「背景简洁，突出角色和关键玩法元素，细节密度适中，不宜过于写实或复杂」，杜绝过度包装导致的货不对板。\\n- 标题需要足够大、足够宽、足够有体积感，成为稳定的品牌识别锚点。\\n- 主体特写与关键瞬间应清晰集中，不要分散成零散背景装饰。\\n- 主特写主体必须优先突出「足球员图标」，不能退化成抽象题材符号或泛化元素堆砌。\\n- 画面不能只是几个元素散落在背景里，必须围绕「足球员图标」这个明确主体和一个正在发生的关键瞬间展开，例如「足球员正在带球或传球的瞬间」。\\n- 画面需要具有设计感，不能直接照搬原始截图，需要提炼其中最有识别度的局部特征进行艺术加工。\\n- 画面整体应体现“标题显著、主体清楚、瞬间明确、位置清晰、层级明确”，并让标题、主体特写与关键瞬间共同构成完整连贯的视觉整体。\\n- 标题位于画面下方中轴附近，形成明确品牌锚点。\\n- 标题应占据较大宽度和足够厚度，具有明显存在感，但不要覆盖画面中上方或中部偏上的主体特写区域的主体特写。\\n- 画面中上方或中部偏上的主体特写区域必须呈现清晰的局部特写和关键瞬间，让人能一眼看清「足球员图标」的动作与结果反馈，即「足球朝着球门方向移动或进入球门」，并感知这款游戏的核心玩法语义，即「通过操作Q版足球运动员在足球场上进行回合制或即时策略对战，目标是射门得分。」。\\n- 画面可围绕 Q版球员、足球场、足球、策略移动/射门、球门 中的少量关键元素展开，但必须突出一个主主体，不要把整体玩法平均铺满。\\n- 除主主体外，只可保留少量能支撑瞬间成立的次要主体，例如 足球、球门、足球场边界元素、时间/比分UI，不要把所有主体平均陈列。\\n- 标题不要遮挡主体动作与结果反馈。\\n- 画面中应保留少量最具代表性的局部元素，但必须经过整理，避免杂乱。\\n- 必须保留「通过操作Q版足球运动员在足球场上进行回合制或即时策略对战，目标是射门得分。」这一核心玩法语义，但不要求把整套玩法链路完整铺开。\\n- 可以保留 Q版球员、足球场、足球、策略移动/射门、球门 等核心元素，但应优先服务于主体特写和关键瞬间，避免平均散落。\\n- 重点表现「弹球式足球策略对战」，并通过局部特写、动作爆发和结果反馈去传达 足球运动 与 策略体育游戏 的结合关系。\\n- 标题「弹弹世界杯：足球全明星」需要有明确的艺术化设计，字形、材质、轮廓、描边、光效或装饰细节应与游戏气质一致，并与主体特写、动作氛围和场景气质自然呼应，但必须保持清晰可读。\\n- 标题应具有 充满活力和卡通感的体育竞技风格，可以带有 粗体字、渐变色填充 或 描边效果，但不要脱离参考图整体风格。\\n- 如果游戏本身画面较粗糙、玩法元素较简单，可以适度进行宣传图式提炼和强化，但这种强化应体现在线条的精致度和色彩的通透感上，不能脱离真实游戏的气质。\\n- 若背景来自实机内容，可适当进行弱化、简化和整理，例如压暗、降对比、降饱和、柔化、减少杂讯，让标题和主体特写都更清楚。\\n- 背景和场景元素只能辅助说明游戏内容，不能喧宾夺主，也不能弱到只剩空背景。背景应保持克制，严禁添加实机不符的内容画面。\\n\\n文字要求：\\n- 画面中除游戏标题外，不要出现其他任何文字、按钮文案、说明文案、宣传语或标签。\\n- 标题文字必须逐字准确显示为「弹弹世界杯：足球全明星」，这 11 个字不能替换、不能改写、不能写成同音字、近义字或其他变体。\\n- 标题必须完整、清晰、可读，不得缺字、错字、连字、变形到无法辨认。\\n- 如果无法稳定保证标题\"},\"quality\":\"medium\",\"size\":\"1536x1024\"},\"files\":[{\"content_type\":\"image/png\",\"field\":\"image[]\",\"filename\":\"image_0.png\",\"size\":307766,\"truncated\":false},{\"content_type\":\"image/png\",\"field\":\"image[]\",\"filename\":\"image_1.png\",\"size\":229349,\"truncated\":false},{\"content_type\":\"image/png\",\"field\":\"image[]\",\"filename\":\"image_2.png\",\"size\":450081,\"truncated\":false}]},\"body_truncated\":false,\"headers\":{\"Accept\":\"\",\"Authorization\":\"Bearer sk-xxx\",\"Content-Type\":\"multipart/form-data; boundary=90804806800ea638acdb6cb1fd85d6ed0937b3672d2e8ec6417a74fa3d3d\"},\"method\":\"POST\",\"url\":\"https://ai.yalian.cloud/v1/images/edits\"},\"source\":\"upstream_do_request\"},\"use_channel\":[\"49\"]},\"channel_id\":49,\"channel_name\":\"星跃-1000RPM\",\"channel_type\":1,\"error_code\":\"do_request_failed\",\"error_type\":\"new_api_error\",\"request_path\":\"/v1/images/edits\",\"status_code\":500}',1782838559,1782838562,0);
INSERT INTO `new-api`.`logs_tmp_06`(`id`,`user_id`,`created_at`,`type`,`content`,`username`,`token_name`,`model_name`,`quota`,`prompt_tokens`,`completion_tokens`,`use_time`,`is_stream`,`channel_id`,`channel_name`,`token_id`,`group`,`ip`,`request_id`,`other`,`started_at`,`finished_at`,`timeout_cleaned`) VALUES(5542037,3,1782838559,5,'status_code=500, upstream error: do request failed','maas','maas','gpt-image-2',0,0,0,3,0,49,NULL,4,'default','','202606301655591690282748268d9d6TpzSXrvV','{\"admin_info\":{\"upstream\":{\"request\":{\"body\":{\"content_type\":\"multipart/form-data\",\"fields\":{\"model\":\"gpt-image-2\",\"prompt\":{\"truncated\":true,\"value\":\"请严格按照以下中文要求，生成 1 张可直接用于中国区游戏商店投放的 16:9 游戏宣传图片。\\n\\n目标场景：16:9 横版游戏宣传图。\\n目标：生成一张兼顾高识别主体特写与标题识别的游戏宣传图。画面需要让标题与主体特写共同构成一个完整、连贯的宣传视觉，让用户优先看清最有识别度的局部主体、关键动作和玩法瞬间，同时通过有设计感的大标题强化品牌识别。标题需要明显突出，但不能遮挡或取代主体特写与关键瞬间。\\n\\n画布：1920x1080，宽高比 16:9。\\n硬性约束：保持构图清晰，并与游戏真实风格一致。\\n\\n游戏信息：\\n- 游戏标题必须显示为「弹弹世界杯：足球全明星」。\\n- 标题共 11 个字，必须逐字准确，不得替换、改写、缺失、错字、同音字、近义字或其他变体。\\n\\n需要保留的视觉识别：\\n- 画风：卡通扁平风格。\\n- 情绪氛围：轻松活泼。\\n\\n参考图要求：\\n- 当前请求附带了开发者提供的参考图，可将其作为玩法内容和视觉方向的补充锚点。\\n- 如果参考图来自实机截图、宣传图或已有素材，应优先提炼其中与真实玩法一致的主体关系、交互对象、行为线索和结果反馈，而不是只提炼表面风格。\\n- 参考图只能帮助校准真实内容、玩法关系和视觉气质，不能把画面带向脱离玩法的概念包装。\\n- 不要直接照搬原图构图、背景、装饰文字、界面排版或 UI。\\n- 若使用实机截图作为参考，只提炼其中最有代表性的玩法符号、环境色调和动作关系，不保留完整截图感和原始布局。\\n- 风格锚定：必须复刻参考图的「保持鲜明的卡通Q版人物和扁平化场景」。背景简洁，突出角色和关键玩法元素，细节密度适中，不宜过于写实或复杂。\\n- 如果参考图带有 HUD、按钮、血条、进度条、数值、角标、卡片、小地图、操作提示或其他游戏内 UI 元素，必须主动忽略并清除；只保留去 UI 后仍然成立的玩法主体和内容关系。\\n- 宣传图只保留纯游戏内容主体、场景关系和美术气质，不保留截图式界面覆盖层，也不要把参考图中的 UI 反馈误当成最终设计元素。\\n\\n差异化方案：\\n- 构图：采用上方主体、下方标题的层次构图，让主体先被看清，再由下方标题完成品牌识别。\\n- 主体位置：主体特写集中在中上方，关键反馈避开下方标题区，避免标题覆盖玩法信息。\\n- 标题位置建议：下方横向标题区。\\n- 标题位于画面下方的稳定横向标题区，整体视觉存在感约占画面 16% 到 22% 左右。\\n- 主体特写与关键瞬间主要落在画面中上方或中部偏上的主体特写区域，与标题位置错开，互不遮挡。\\n\\n场景要求：\\n- 这是一张游戏宣传图，不是纯标题海报，也不是完整截图直接贴字。\\n- 必须保留与游戏一致的核心玩法语义，但不要求把完整玩法流程完整铺开。\\n- 标题文字是重要的宣传识别元素，需要明显突出，但不能压制主体特写与关键瞬间，并应顺着主体动作、场景走势和整体节奏自然融入画面。\\n- 画面使用艺术设计，在保留实机语义的情况下，脱离截图重新编排场景布局，优先选择最有识别度的局部主体与关键玩法瞬间进行艺术重绘和表达，确保角色特征、核心气质、玩家体验与真实游戏一致。\\n- 标题在下方托住画面，主体特写和关键动作在上方展开，标题像场景的一部分而不是后期贴字。\\n- 标题放在画面下方的稳定横向标题区，主体特写与关键瞬间放在画面中上方或中部偏上的主体特写区域，两者位置错开，不要互相遮挡，同时要保持构图呼应，不要像后期单独贴上的独立层。\\n- 视觉还原优先级：必须确保生成的画面在美术形式上与参考图高度对齐，严格遵循「保持鲜明的卡通Q版人物和扁平化场景」，并满足「背景简洁，突出角色和关键玩法元素，细节密度适中，不宜过于写实或复杂」，杜绝过度包装导致的货不对板。\\n- 标题需要足够大、足够宽、足够有体积感，成为稳定的品牌识别锚点。\\n- 主体特写与关键瞬间应清晰集中，不要分散成零散背景装饰。\\n- 主特写主体必须优先突出「足球员图标」，不能退化成抽象题材符号或泛化元素堆砌。\\n- 画面不能只是几个元素散落在背景里，必须围绕「足球员图标」这个明确主体和一个正在发生的关键瞬间展开，例如「足球员正在带球或传球的瞬间」。\\n- 画面需要具有设计感，不能直接照搬原始截图，需要提炼其中最有识别度的局部特征进行艺术加工。\\n- 画面整体应体现“标题显著、主体清楚、瞬间明确、位置清晰、层级明确”，并让标题、主体特写与关键瞬间共同构成完整连贯的视觉整体。\\n- 标题位于画面下方中轴附近，形成明确品牌锚点。\\n- 标题应占据较大宽度和足够厚度，具有明显存在感，但不要覆盖画面中上方或中部偏上的主体特写区域的主体特写。\\n- 画面中上方或中部偏上的主体特写区域必须呈现清晰的局部特写和关键瞬间，让人能一眼看清「足球员图标」的动作与结果反馈，即「足球朝着球门方向移动或进入球门」，并感知这款游戏的核心玩法语义，即「通过操作Q版足球运动员在足球场上进行回合制或即时策略对战，目标是射门得分。」。\\n- 画面可围绕 Q版球员、足球场、足球、策略移动/射门、球门 中的少量关键元素展开，但必须突出一个主主体，不要把整体玩法平均铺满。\\n- 除主主体外，只可保留少量能支撑瞬间成立的次要主体，例如 足球、球门、足球场边界元素、时间/比分UI，不要把所有主体平均陈列。\\n- 标题不要遮挡主体动作与结果反馈。\\n- 画面中应保留少量最具代表性的局部元素，但必须经过整理，避免杂乱。\\n- 必须保留「通过操作Q版足球运动员在足球场上进行回合制或即时策略对战，目标是射门得分。」这一核心玩法语义，但不要求把整套玩法链路完整铺开。\\n- 可以保留 Q版球员、足球场、足球、策略移动/射门、球门 等核心元素，但应优先服务于主体特写和关键瞬间，避免平均散落。\\n- 重点表现「弹球式足球策略对战」，并通过局部特写、动作爆发和结果反馈去传达 足球运动 与 策略体育游戏 的结合关系。\\n- 标题「弹弹世界杯：足球全明星」需要有明确的艺术化设计，字形、材质、轮廓、描边、光效或装饰细节应与游戏气质一致，并与主体特写、动作氛围和场景气质自然呼应，但必须保持清晰可读。\\n- 标题应具有 充满活力和卡通感的体育竞技风格，可以带有 粗体字、渐变色填充 或 描边效果，但不要脱离参考图整体风格。\\n- 如果游戏本身画面较粗糙、玩法元素较简单，可以适度进行宣传图式提炼和强化，但这种强化应体现在线条的精致度和色彩的通透感上，不能脱离真实游戏的气质。\\n- 若背景来自实机内容，可适当进行弱化、简化和整理，例如压暗、降对比、降饱和、柔化、减少杂讯，让标题和主体特写都更清楚。\\n- 背景和场景元素只能辅助说明游戏内容，不能喧宾夺主，也不能弱到只剩空背景。背景应保持克制，严禁添加实机不符的内容画面。\\n\\n文字要求：\\n- 画面中除游戏标题外，不要出现其他任何文字、按钮文案、说明文案、宣传语或标签。\\n- 标题文字必须逐字准确显示为「弹弹世界杯：足球全明星」，这 11 个字不能替换、不能改写、不能写成同音字、近义字或其他变体。\\n- 标题必须完整、清晰、可读，不得缺字、错字、连字、变形到无法辨认。\\n- 如果无法稳定保证标题\"},\"quality\":\"medium\",\"size\":\"1536x1024\"},\"files\":[{\"content_type\":\"image/png\",\"field\":\"image[]\",\"filename\":\"image_0.png\",\"size\":307766,\"truncated\":false},{\"content_type\":\"image/png\",\"field\":\"image[]\",\"filename\":\"image_1.png\",\"size\":229349,\"truncated\":fals