INSERT INTO `new-api`.`logs_tmp_06`(`id`,`user_id`,`created_at`,`type`,`content`,`username`,`token_name`,`model_name`,`quota`,`prompt_tokens`,`completion_tokens`,`use_time`,`is_stream`,`channel_id`,`channel_name`,`token_id`,`group`,`ip`,`request_id`,`other`,`started_at`,`finished_at`,`timeout_cleaned`) VALUES(5542038,3,1782838584,5,'status_code=500, upstream error: do request failed','maas','maas','gpt-image-2',0,0,0,3,0,49,NULL,4,'default','','202606301656244674755608268d9d6uX9yRDiz','{\"admin_info\":{\"upstream\":{\"request\":{\"body\":{\"content_type\":\"multipart/form-data\",\"fields\":{\"model\":\"gpt-image-2\",\"prompt\":\"请对原图进行编辑。编辑指令：基于原图制作《折翼之歌》EP18 FULL_REDO S05 的高清真人电影连续首帧，保持大千制药厂休息室同一空间、同一光线方向、同一人物身份、水果盘状态和真实电影质感，但把剧情推进到下一镜第0秒：陶立坐在靠窗床位边，手里拿着一块苹果正在咀嚼或准备送到嘴边，浅色水果盘稳定放在他膝盖上或一只手托着；魏恩瑶完整入镜，站在床边稍右侧，听他说话，准备转向窗边。\\n\\n必须修正原尾帧问题：魏恩瑶不能被画面右侧裁切，必须完整显示头部、上半身、白大褂、灰色背包、牛仔裤和白鞋；陶立不能被裁头裁手，水果盘不能变形。\\n\\n必须严格锁定角色：陶立是短黑发中国男性，旧蓝色牛仔工装夹克和同色工装裤，右小腿白色绷带，黑色工靴，受伤后疲惫但硬撑，坐在靠窗床位，不能换脸、不能换衣服；右小腿白绷带必须可见或被床沿自然少量遮挡，但不能消失。魏恩瑶是年轻中国女性，眼镜，黑色马尾，白色实验室外套，浅蓝衬衫，牛仔裤，白色运动鞋，灰色背包，不能换成其他医生或护士，不能去掉眼镜、白大褂、背包。\\n\\n道具锁定：水果盘是浅色陶瓷盘，盘中有切好的苹果、梨、橘子瓣；陶立手中拿的是一块苹果。水果盘必须在陶立手中或膝盖上，不能悬空，不能变成桶、盒子、药品、血污、医疗垃圾或其他道具。\\n\\n空间：旧水泥墙、铁架上下铺、靠窗床位、窗外药厂建筑、桌椅保持合理，地面连续干净。不要新增桶、垃圾桶、医疗垃圾、血污、纸箱、标签、武器、无关工具。不要画面文字、英文、乱码、Logo、水印。\\n\\n表演起点：陶立边嚼苹果边抬眼看向魏恩瑶，眉头微挑，疲惫但追问的神情清楚，嘴唇和下颌有咀嚼起点，手指自然捏着苹果块；魏恩瑶听到追问前神情微微沉下，眼神闪避或低垂，手轻压背包肩带，准备摇头走向窗边。两人都有自然微表情和微动作起点，不是摆拍，不能呆滞无神。\\n\\n画质要求：clean high-resolution cinema image, ultra sharp but natural, real live-action cinema frame, natural skin texture, clear facial details, clear eyes, clear lips, clear hands and fingers, clear fabric texture, clean concrete wall texture, clean floor texture, no noise, no grain, no low-resolution video frame, no AI sharpening artifacts, no dirty edge halos, no plastic skin, no painterly look, no game CG。构图为16:9横版电影画面，人物完整，不裁头、不裁脚、不裁手，无缺肢断肢，无重复身体或重复条带。\",\"quality\":\"medium\",\"size\":\"1536x1024\"},\"files\":[{\"content_type\":\"image/jpeg\",\"field\":\"image[]\",\"filename\":\"image_0.jpeg\",\"size\":298609,\"truncated\":false},{\"content_type\":\"image/webp\",\"field\":\"image[]\",\"filename\":\"image_1.webp\",\"size\":227116,\"truncated\":false},{\"content_type\":\"image/jpeg\",\"field\":\"image[]\",\"filename\":\"image_2.jpeg\",\"size\":474986,\"truncated\":false},{\"content_type\":\"image/png\",\"field\":\"image[]\",\"filename\":\"image_3.png\",\"size\":874684,\"truncated\":false},{\"content_type\":\"image/png\",\"field\":\"image[]\",\"filename\":\"image_4.png\",\"size\":1654604,\"truncated\":false},{\"content_type\":\"image/png\",\"field\":\"image[]\",\"filename\":\"image_5.png\",\"size\":2194425,\"truncated\":false},{\"content_type\":\"image/png\",\"field\":\"image[]\",\"filename\":\"image_6.png\",\"size\":4840077,\"truncated\":true}]},\"body_truncated\":false,\"headers\":{\"Accept\":\"\",\"Authorization\":\"Bearer sk-xxx\",\"Content-Type\":\"multipart/form-data; boundary=78882847c450e0417733b2cbb177deba1482a07d7ed59b6c94982e4cf47f\"},\"method\":\"POST\",\"url\":\"https://ai.yalian.cloud/v1/images/edits\"},\"source\":\"upstream_do_request\"},\"use_channel\":[\"49\"]},\"channel_id\":49,\"channel_name\":\"星跃-1000RPM\",\"channel_type\":1,\"error_code\":\"do_request_failed\",\"error_type\":\"new_api_error\",\"request_path\":\"/v1/images/edits\",\"status_code\":500}',1782838584,1782838587,0);
