INSERT INTO `new-api`.`logs_tmp_06`(`id`,`user_id`,`created_at`,`type`,`content`,`username`,`token_name`,`model_name`,`quota`,`prompt_tokens`,`completion_tokens`,`use_time`,`is_stream`,`channel_id`,`channel_name`,`token_id`,`group`,`ip`,`request_id`,`other`,`started_at`,`finished_at`,`timeout_cleaned`) VALUES(5542064,3,1782839036,5,'status_code=500, upstream error: do request failed','maas','maas','gpt-image-2',0,0,0,3,0,49,NULL,4,'default','','202606301703563231500488268d9d62aqP0HjT','{\"admin_info\":{\"upstream\":{\"request\":{\"body\":{\"content_type\":\"multipart/form-data\",\"fields\":{\"model\":\"gpt-image-2\",\"prompt\":\"请对原图进行编辑。编辑指令：基于原图重做为《折翼之歌》第十六集16-1B高清连续首帧，保持上一镜尾帧的剧情连续性，但修复画质和空间：真人电影风格，16:9，高清无噪点。必须保持陶立仍被巨蛙飞翼尖刺入腹部、右手被从巨蛙嘴里伸出的长舌缠住控制，旧蓝色牛仔工装夹克和同色工装裤、右小腿白色绷带、黑色工靴正确。陶立不再挥刀成功，右手被舌头拉住，脸部痛苦绷紧，身体半悬空或被翼尖顶住。魏恩瑶必须严格保持白色实验室外套、浅蓝衬衫、牛仔裤、白鞋、灰色背包、马尾、眼镜，她已经跑到陶立侧前方几步远，正一边奔跑一边用一只手从马尾上取下黑色皮筋，另一只手握着黑色电击棍，准备把自己的手和电棍绑在一起；动作真实，不能已经攻击，不能被扇飞。后景仍是巨大的寄生巨谐蛙，白色起伏肚皮像一堵墙，背后有飞翼，嘴里伸出的长舌缠住陶立右手。恢复更宽一点的空间，保留地面上低位实体手电筒或至少保留来自地面低位的柔和手电光束，不能让光源凭空出现。场景是极黑暗的热带雨林馆干涸池塘，暗部大块干净，地面matte low-contrast damp soil, broad clean shadow areas, soft diffused flashlight, no specular wet highlights, no shiny pebble mosaic, no scale-like ground texture, no high-contrast micro highlights。不要出现周进、徐以太、李维康、闪光弹、卵、医疗包、火焰、文字、英文、Logo、水印。clean high-resolution cinema image, ultra sharp but natural, real live-action cinema frame, natural skin texture, clear facial details, clear eyes, clear lips, clear hands and fingers, clear fabric texture, no noise, no grain, no low-resolution video frame, no AI sharpening artifacts, no dirty edge halos, no plastic skin, no painterly look, no game CG。\",\"quality\":\"medium\",\"size\":\"1536x1024\"},\"files\":[{\"content_type\":\"image/jpeg\",\"field\":\"image[]\",\"filename\":\"image_0.jpeg\",\"size\":338949,\"truncated\":false},{\"content_type\":\"image/jpeg\",\"field\":\"image[]\",\"filename\":\"image_1.jpeg\",\"size\":195864,\"truncated\":false},{\"content_type\":\"image/jpeg\",\"