INSERT INTO `new-api`.`logs_tmp_06`(`id`,`user_id`,`created_at`,`type`,`content`,`username`,`token_name`,`model_name`,`quota`,`prompt_tokens`,`completion_tokens`,`use_time`,`is_stream`,`channel_id`,`channel_name`,`token_id`,`group`,`ip`,`request_id`,`other`,`started_at`,`finished_at`,`timeout_cleaned`) VALUES(5542189,3,1782842688,5,'status_code=500, upstream error: do request failed','maas','maas','gpt-image-2',0,0,0,3,0,49,NULL,4,'default','','202606301804484583382368268d9d6cSifKOpu','{\"admin_info\":{\"upstream\":{\"request\":{\"body\":{\"model\":\"gpt-image-2\",\"n\":1,\"prompt\":\"横版16:9顶视图游戏地图，锈蚀沙驿，暗黑风、史诗风、CG风、写实风。画面为荒漠中的废弃驿站遗址，镜头垂直俯视，地图构图清晰；驿站大半建筑被厚重黄沙掩埋，只露出锈蚀金属屋顶边缘、破损木梁、残破石墙和坍塌门廊；周围有残垣断壁、断裂墙基、半埋石柱、碎石、风蚀木板、锈蚀铁链、废弃货箱和被沙覆盖的道路痕迹。驿站深处明确有一张古旧石桌和两个石凳，位于较隐秘的内院或半埋房间中，石桌石凳被少量黄沙覆盖但清晰可见。整体色调为暗金黄沙、锈红、冷灰、黑褐，阴冷风沙薄雾，强烈明暗对比，电影级光影，宏大荒凉古遗迹氛围，高质量环境概念设计，适合作为游戏大地图背景，无人物近景，无文字水印。\",\"quality\":\"medium\",\"size\":\"1536x1024\"},\"body_truncated\":false,\"headers\":{\"Accept\":\"\",\"Authorization\":\"Bearer sk-xxx\",\"Content-Type\":\"application/json\"},\"method\":\"POST\",\"url\":\"https://ai.yalian.cloud/v1/images/generations\"},\"source\":\"upstream_do_request\"},\"use_channel\":[\"49\"]},\"channel_id\":49,\"channel_name\":\"星跃-1000RPM\",\"channel_type\":1,\"error_code\":\"do_request_failed\",\"error_type\":\"new_api_error\",\"request_path\":\"/v1/images/generations\",\"status_code\":500}',1782842688,1782842691,0);
INSERT INTO `new-api`.`logs_tmp_06`(`id`,`user_id`,`created_at`,`type`,`content`,`username`,`token_name`,`model_name`,`quota`,`prompt_tokens`,`completion_tokens`,`use_time`,`is_stream`,`channel_id`,`channel_name`,`token_id`,`group`,`ip`,`request_id`,`other`,`started_at`,`finished_at`,`timeout_cleaned`) VALUES(5542197,3,1782843482,5,'status_code=500, upstream error: do request failed','maas','maas','gpt-image-2',0,0,0,3,0,49,NULL,4,'default','','20260630181802461874568268d9d6GbpEvOSY','{\"admin_info\":{\"upstream\":{\"request\":{\"body\":{\"model\":\"gpt-image-2\",\"n\":1,\"prompt\":\"《折翼之歌》第十七集场景主图：大千制药厂休息室，真人电影风格，16:9，无人物。旧制药厂内部临时避难休息室，大通铺/简易床铺沿墙排列，旧水泥墙，墙面有潮痕和工业建筑质感，冷白顶灯很弱，空间昏暗但画面高清干净。房间内有简易桌椅、床边小柜、医用用品但不要出现文字标签。一个角落有垃圾桶，桶里可见一卷带血绷带，用于剧情暗示，但不要血腥夸张。窗边能看到外面制药厂建筑轮廓，空间布局要适合后续：陶立躺在床上接受处理，魏恩瑶在床边，周进站在窗边看外面。不要出现人物，不要出现英文、乱码、Logo、水印、标语。clean high-resolution cinema image, ultra sharp but natural, real live-action cinema frame, clean concrete wall texture, clean floor texture, clear bedding fabric texture, no noise, no grain, no low-resolution video frame, no AI sharpening artifacts, no dirty edge halos, no plastic skin, no painterly look, no game CG。\",\"quality\":\"medium\",\"size\":\"1536x1024\"},\"body_truncated\":false,\"headers\":{\"Accept\":\"\",\"Authorization\":\"Bearer sk-xxx\",\"Content-Type\":\"application/json\"},\"method\":\"POST\",\"url\":\"https://ai.yalian.cloud/v1/images/generations\"},\"source\":\"upstream_do_request\"},\"use_channel\":[\"49\"]},\"channel_id\":49,\"channel_name\":\"星跃-1000RPM\",\"channel_type\":1,\"error_code\":\"do_request_failed\",\"error_type\":\"new_api_error\",\"request_path\":\"/v1/images/generations\",\"status_code\":500}',1782843482,1782843485,0);
INSERT INTO `new-api`.`logs_tmp_06`(`id`,`user_id`,`created_at`,`type`,`content`,`username`,`token_name`,`model_name`,`quota`,`prompt_tokens`,`completion_tokens`,`use_time`,`is_stream`,`channel_id`,`channel_name`,`token_id`,`group`,`ip`,`request_id`,`other`,`started_at`,`finished_at`,`timeout_cleaned`) VALUES(5542199,3,1782843519,5,'status_code=500, upstream error: do request failed','maas','maas','gpt-image-2',0,0,0,3,0,49,NULL,4,'default','','202606301818397202918268d9d66CUNpvsC','{\"admin_info\":{\"upstream\":{\"request\":{\"body\":{\"content_type\":\"multipart/form-data\",\"fields\":{\"model\":\"gpt-image-2\",\"prompt\":{\"truncated\":true,\"value\":\"请严格按照以下中文要求，生成 1 张可直接用于中国区游戏商店投放的 16:9 游戏宣传图片。\\n\\n目标场景：16:9 横版游戏宣传图。\\n目标：生成一张兼顾高识别主体特写与标题识别的游戏宣传图。画面需要让标题与主体特写共同构成一个完整、连贯的宣传视觉，让用户优先看清最有识别度的局部主体、关键动作和玩法瞬间，同时通过有设计感的大标题强化品牌识别。标题需要明显突出，但不能遮挡或取代主体特写与关键瞬间。\\n\\n画布：1920x1080，宽高比 16:9。\\n硬性约束：保持构图清晰，并与游戏真实风格一致。\\n\\n游戏信息：\\n- 游戏标题必须显示为「武林秘境」。\\n- 标题共 4 个字，必须逐字准确，不得替换、改写、缺失、错字、同音字、近义字或其他变体。\\n\\n需要保留的视觉识别：\\n- 画风：像素武侠风。\\n- 情绪氛围：沉浸、探索、战斗。\\n\\n参考图要求：\\n- 当前请求附带了开发者提供的参考图，可将其作为玩法内容和视觉方向的补充锚点。\\n- 如果参考图来自实机截图、宣传图或已有素材，应优先提炼其中与真实玩法一致的主体关系、交互对象、行为线索和结果反馈，而不是只提炼表面风格。\\n- 参考图只能帮助校准真实内容、玩法关系和视觉气质，不能把画面带向脱离玩法的概念包装。\\n- 不要直接照搬原图构图、背景、装饰文字、界面排版或 UI。\\n- 若使用实机截图作为参考，只提炼其中最有代表性的玩法符号、环境色调和动作关系，不保留完整截图感和原始布局。\\n- 风格锚定：必须复刻参考图的「保持像素画风，尤其是在角色和场景元素上」。保持整体界面的简洁性，突出文字信息和核心角色，背景可适度简化。\\n- 如果参考图带有 HUD、按钮、血条、进度条、数值、角标、卡片、小地图、操作提示或其他游戏内 UI 元素，必须主动忽略并清除；只保留去 UI 后仍然成立的玩法主体和内容关系。\\n- 宣传图只保留纯游戏内容主体、场景关系和美术气质，不保留截图式界面覆盖层，也不要把参考图中的 UI 反馈误当成最终设计元素。\\n\\n差异化方案：\\n- 构图：采用上方标题、下方主体的横向分层构图，避免把参考截图原样铺底。\\n- 主体位置：主体特写集中在中下部，可略微偏左或偏右，让动作方向与标题形成呼应。\\n- 标题位置建议：上方横向标题区。\\n- 标题位于画面上方的稳定横向标题区，整体视觉存在感约占画面 18% 到 24% 左右。\\n- 主体特写与关键瞬间主要落在画面中下方或中部偏下的主体特写区域，与标题位置错开，互不遮挡。\\n\\n场景要求：\\n- 这是一张游戏宣传图，不是纯标题海报，也不是完整截图直接贴字。\\n- 必须保留与游戏一致的核心玩法语义，但不要求把完整玩法流程完整铺开。\\n- 标题文字是重要的宣传识别元素，需要明显突出，但不能压制主体特写与关键瞬间，并应顺着主体动作、场景走势和整体节奏自然融入画面。\\n- 画面使用艺术设计，在保留实机语义的情况下，脱离截图重新编排场景布局，优先选择最有识别度的局部主体与关键玩法瞬间进行艺术重绘和表达，确保角色特征、核心气质、玩家体验与真实游戏一致。\\n- 标题在上方形成品牌锚点，主体特写和关键动作在下方展开，标题顺着场景走势压住画面节奏但不遮挡主体。\\n- 标题放在画面上方的稳定横向标题区，主体特写与关键瞬间放在画面中下方或中部偏下的主体特写区域，两者位置错开，不要互相遮挡，同时要保持构图呼应，不要像后期单独贴上的独立层。\\n- 视觉还原优先级：必须确保生成的画面在美术形式上与参考图高度对齐，严格遵循「保持像素画风，尤其是在角色和场景元素上」，并满足「保持整体界面的简洁性，突出文字信息和核心角色，背景可适度简化」，杜绝过度包装导致的货不对板。\\n- 标题需要足够大、足够宽、足够有体积感，成为稳定的品牌识别锚点。\\n- 主体特写与关键瞬间应清晰集中，不要分散成零散背景装饰。\\n- 主特写主体必须优先突出「身着武侠服饰的半身像素角色」，不能退化成抽象题材符号或泛化元素堆砌。\\n- 画面不能只是几个元素散落在背景里，必须围绕「身着武侠服饰的半身像素角色」这个明确主体和一个正在发生的关键瞬间展开，例如「角色进行攻击或处于战斗状态」。\\n- 画面需要具有设计感，不能直接照搬原始截图，需要提炼其中最有识别度的局部特征进行艺术加工。\\n- 画面整体应体现“标题显著、主体清楚、瞬间明确、位置清晰、层级明确”，并让标题、主体特写与关键瞬间共同构成完整连贯的视觉整体。\\n- 标题位于画面上方中轴附近，形成明确品牌锚点。\\n- 标题应占据较大宽度和足够厚度，具有明显存在感，但不要覆盖画面中下方或中部偏下的主体特写区域的主体特写。\\n- 画面中下方或中部偏下的主体特写区域必须呈现清晰的局部特写和关键瞬间，让人能一眼看清「身着武侠服饰的半身像素角色」的动作与结果反馈，即「伤害数字弹窗或血量条下降」，并感知这款游戏的核心玩法语义，即「玩家扮演侠客在像素江湖中探索、战斗并提升武学修为。」。\\n- 画面可围绕 文字剧情、回合制战斗、角色养成、Roguelike 中的少量关键元素展开，但必须突出一个主主体，不要把整体玩法平均铺满。\\n- 除主主体外，只可保留少量能支撑瞬间成立的次要主体，例如 红色的血量条、任务文本、战斗伤害数字，不要把所有主体平均陈列。\\n- 标题不要遮挡主体动作与结果反馈。\\n- 画面中应保留少量最具代表性的局部元素，但必须经过整理，避免杂乱。\\n- 必须保留「玩家扮演侠客在像素江湖中探索、战斗并提升武学修为。」这一核心玩法语义，但不要求把整套玩法链路完整铺开。\\n- 可以保留 文字剧情、回合制战斗、角色养成、Roguelike 等核心元素，但应优先服务于主体特写和关键瞬间，避免平均散落。\\n- 重点表现「以文字叙述和数值反馈为主的像素武侠RPG」，并通过局部特写、动作爆发和结果反馈去传达 武侠 与 文字角色扮演 的结合关系。\\n- 标题「武林秘境」需要有明确的艺术化设计，字形、材质、轮廓、描边、光效或装饰细节应与游戏气质一致，并与主体特写、动作氛围和场景气质自然呼应，但必须保持清晰可读。\\n- 标题应具有 硬朗、内敛、有江湖气息，可以带有 笔锋凌厉的中文书法字体、黑白或暗色调为主 或 边缘带有武侠纹理装饰，但不要脱离参考图整体风格。\\n- 如果游戏本身画面较粗糙、玩法元素较简单，可以适度进行宣传图式提炼和强化，但这种强化应体现在线条的精致度和色彩的通透感上，不能脱离真实游戏的气质。\\n- 若背景来自实机内容，可适当进行弱化、简化和整理，例如压暗、降对比、降饱和、柔化、减少杂讯，让标题和主体特写都更清楚。\\n- 背景和场景元素只能辅助说明游戏内容，不能喧宾夺主，也不能弱到只剩空背景。背景应保持克制，严禁添加实机不符的内容画面。\\n\\n文字要求：\\n- 画面中除游戏标题外，不要出现其他任何文字、按钮文案、说明文案、宣传语或标签。\\n- 标题文字必须逐字准确显示为「武林秘境」，这 4 个字不能替换、不能改写、不能写成同音字、近义字或其他变体。\\n- 标题必须完整、清晰、可读，不得缺字、错字、连字、变形到无法辨认。\\n- 如果无法稳定保证标题文字准确，请优�\"},\"quality\":\"medium\",\"size\":\"1536x1024\"},\"files\":[{\"content_type\":\"image/jpeg\",\"field\":\"image[]\",\"filename\":\"image_0.jpeg\",\"size\":718562,\"truncated\":false},{\"content_type\":\"image/jpeg\",\"field\":\"image[]\",\"filename\":\"image_1.jpeg\",\"size\":854474,\"truncated\":false},{\"content_type\":\"image/jpeg\",\"field\":\"image[]\",\"filename\":\"image_2.jpeg\",\"size\":338456,\"truncated\":false}]},\"body_truncated\":false,\"headers\":{\"Accept\":\"\",\"Authorization\":\"Bearer sk-xxx\",\"Content-Type\":\"multipart/form-data; boundary=6738a023749d3978ea6553c500e6b7813fbf1a4b9c96e39ce68ff05487ef\"},\"method\":\"POST\",\"url\":\"https://ai.yalian.cloud/v1/images/edits\"},\"source\":\"upstream_do_request\"},\"use_channel\":[\"49\"]},\"channel_id\":49,\"channel_name\":\"星跃-1000RPM\",\"channel_type\":1,\"error_code\":\"do_request_failed\",\"error_type\":\"new_api_error\",\"request_path\":\"/v1/images/edits\",\"status_code\":500}',1782843519,1782843522,0);
INSERT INTO `new-api`.`logs_tmp_06`(`id`,`user_id`,`created_at`,`type`,`content`,`username`,`token_name`,`model_name`,`quota`,`prompt_tokens`,`completion_tokens`,`use_time`,`is_stream`,`channel_id`,`channel_name`,`token_id`,`group`,`ip`,`request_id`,`other`,`started_at`,`finished_at`,`timeout_cleaned`) VALUES(5542202,3,1782843619,5,'status_code=500, upstream error: do request failed','maas','maas','gpt-image-2',0,0,0,3,0,49,NULL,4,'default','','202606301820192229272888268d9d6UtHLdqyK','{\"admin_info\":{\"upstream\":{\"request\":{\"body\":{\"content_type\":\"multipart/form-data\",\"fields\":{\"model\":\"gpt-image-2\",\"prompt\":{\"truncated\":true,\"value\":\"请严格按照以下中文要求，生成 1 张可直接用于中国区游戏商店投放的 16:9 游戏宣传图片。\\n\\n目标场景：16:9 横版游戏宣传图。\\n目标：生成一张兼顾高识别主体特写与标题识别的游戏宣传图。画面需要让标题与主体特写共同构成一个完整、连贯的宣传视觉，让用户优先看清最有识别度的局部主体、关键动作和玩法瞬间，同时通过有设计感的大标题强化品牌识别。标题需要明显突出，但不能遮挡或取代主体特写与关键瞬间。\\n\\n画布：1920x1080，宽高比 16:9。\\n硬性约束：保持构图清晰，并与游戏真实风格一致。\\n\\n游戏信息：\\n- 游戏标题必须显示为「足球战术大师」。\\n- 标题共 6 个字，必须逐字准确，不得替换、改写、缺失、错字、同音字、近义字或其他变体。\\n\\n需要保留的视觉识别：\\n- 画风：极简界面UI。\\n- 情绪氛围：策略性、职业感。\\n\\n参考图要求：\\n- 当前请求附带了开发者提供的参考图，可将其作为玩法内容和视觉方向的补充锚点。\\n- 如果参考图来自实机截图、宣传图或已有素材，应优先提炼其中与真实玩法一致的主体关系、交互对象、行为线索和结果反馈，而不是只提炼表面风格。\\n- 参考图只能帮助校准真实内容、玩法关系和视觉气质，不能把画面带向脱离玩法的概念包装。\\n- 不要直接照搬原图构图、背景、装饰文字、界面排版或 UI。\\n- 若使用实机截图作为参考，只提炼其中最有代表性的玩法符号、环境色调和动作关系，不保留完整截图感和原始布局。\\n- 风格锚定：必须复刻参考图的「保持界面UI的简洁与功能性，避免写实主义插画」。背景应保持与游戏内界面一致的低复杂度，主体为游戏UI元素，细节体现在文字信息和按钮设计上。。\\n- 如果参考图带有 HUD、按钮、血条、进度条、数值、角标、卡片、小地图、操作提示或其他游戏内 UI 元素，必须主动忽略并清除；只保留去 UI 后仍然成立的玩法主体和内容关系。\\n- 宣传图只保留纯游戏内容主体、场景关系和美术气质，不保留截图式界面覆盖层，也不要把参考图中的 UI 反馈误当成最终设计元素。\\n\\n差异化方案：\\n- 构图：采用左上标题、右侧主体的对角线构图，让视线从标题自然落到关键动作。\\n- 主体位置：主体特写集中在右侧或右下，关键反馈留在标题对角区域，避免互相遮挡。\\n- 标题位置建议：左上标题区。\\n- 标题位于画面左上方的稳定标题区，整体视觉存在感约占画面 16% 到 22% 左右。\\n- 主体特写与关键瞬间主要落在画面右侧或右下方的主体特写区域，与标题位置错开，互不遮挡。\\n\\n场景要求：\\n- 这是一张游戏宣传图，不是纯标题海报，也不是完整截图直接贴字。\\n- 必须保留与游戏一致的核心玩法语义，但不要求把完整玩法流程完整铺开。\\n- 标题文字是重要的宣传识别元素，需要明显突出，但不能压制主体特写与关键瞬间，并应顺着主体动作、场景走势和整体节奏自然融入画面。\\n- 画面使用艺术设计，在保留实机语义的情况下，脱离截图重新编排场景布局，优先选择最有识别度的局部主体与关键玩法瞬间进行艺术重绘和表达，确保角色特征、核心气质、玩家体验与真实游戏一致。\\n- 标题在左上形成品牌锚点，主体动作从中部向右侧展开，标题与主体之间保留清晰呼吸感。\\n- 标题放在画面左上方的稳定标题区，主体特写与关键瞬间放在画面右侧或右下方的主体特写区域，两者位置错开，不要互相遮挡，同时要保持构图呼应，不要像后期单独贴上的独立层。\\n- 视觉还原优先级：必须确保生成的画面在美术形式上与参考图高度对齐，严格遵循「保持界面UI的简洁与功能性，避免写实主义插画」，并满足「背景应保持与游戏内界面一致的低复杂度，主体为游戏UI元素，细节体现在文字信息和按钮设计上。」，杜绝过度包装导致的货不对板。\\n- 标题需要足够大、足够宽、足够有体积感，成为稳定的品牌识别锚点。\\n- 主体特写与关键瞬间应清晰集中，不要分散成零散背景装饰。\\n- 主特写主体必须优先突出「战术面板、选择区域或应用按钮」，不能退化成抽象题材符号或泛化元素堆砌。\\n- 画面不能只是几个元素散落在背景里，必须围绕「战术面板、选择区域或应用按钮」这个明确主体和一个正在发生的关键瞬间展开，例如「选择战术或进入联赛」。\\n- 画面需要具有设计感，不能直接照搬原始截图，需要提炼其中最有识别度的局部特征进行艺术加工。\\n- 画面整体应体现“标题显著、主体清楚、瞬间明确、位置清晰、层级明确”，并让标题、主体特写与关键瞬间共同构成完整连贯的视觉整体。\\n- 标题位于画面左上侧，形成明确品牌锚点。\\n- 标题应占据较大宽度和足够厚度，具有明显存在感，但不要覆盖画面右侧或右下方的主体特写区域的主体特写。\\n- 画面右侧或右下方的主体特写区域必须呈现清晰的局部特写和关键瞬间，让人能一眼看清「战术面板、选择区域或应用按钮」的动作与结果反馈，即「战术应用或联赛开始」，并感知这款游戏的核心玩法语义，即「玩家通过选择战术、管理球队，提升战绩并在不同联赛中晋级，最终成为战术大师的策略模拟游戏。」。\\n- 画面可围绕 战术选择与应用、球队管理、联赛晋级、资源管理 中的少量关键元素展开，但必须突出一个主主体，不要把整体玩法平均铺满。\\n- 除主主体外，只可保留少量能支撑瞬间成立的次要主体，例如 中超联赛信息、球队名称与等级，不要把所有主体平均陈列。\\n- 标题不要遮挡主体动作与结果反馈。\\n- 画面中应保留少量最具代表性的局部元素，但必须经过整理，避免杂乱。\\n- 必须保留「玩家通过选择战术、管理球队，提升战绩并在不同联赛中晋级，最终成为战术大师的策略模拟游戏。」这一核心玩法语义，但不要求把整套玩法链路完整铺开。\\n- 可以保留 战术选择与应用、球队管理、联赛晋级、资源管理 等核心元素，但应优先服务于主体特写和关键瞬间，避免平均散落。\\n- 重点表现「模拟足球经理，侧重战术层面决策，无球场竞技画面。」，并通过局部特写、动作爆发和结果反馈去传达 足球战术、联赛管理 与 模拟经营、体育策略 的结合关系。\\n- 标题「足球战术大师」需要有明确的艺术化设计，字形、材质、轮廓、描边、光效或装饰细节应与游戏气质一致，并与主体特写、动作氛围和场景气质自然呼应，但必须保持清晰可读。\\n- 标题应具有 简洁、专业、力量感，可以带有 字体颜色明亮、字体排版整齐 或 可能包含足球相关简洁图形元素，但不要脱离参考图整体风格。\\n- 如果游戏本身画面较粗糙、玩法元素较简单，可以适度进行宣传图式提炼和强化，但这种强化应体现在线条的精致度和色彩的通透感上，不能脱离真实游戏的气质。\\n- 若背景来自实机内容，可适当进行弱化、简化和整理，例如压暗、降对比、降饱和、柔化、减少杂讯，让标题和主体特写都更清楚。\\n- 背景和场景元素只能辅助说明游戏内容，不能喧宾夺主，也不能弱到只剩空背景。背景应保持克制，严禁添加实机不符的内容画面。\\n\\n文字要求：\\n- 画面中除游戏标题外，不要出现其他任何文字、按钮文案、说明文案、宣传语或标签。\\n- 标题文字必须逐字准确显示为「足球战术大师」，这 6 个字不能替换、不能改写、不能写成同音字\"},\"quality\":\"medium\",\"size\":\"1536x1024\"},\"files\":[{\"content_type\":\"image/png\",\"field\":\"image[]\",\"filename\":\"image_0.png\",\"size\":125452,\"truncated\":false},{\"content_type\":\"image/png\",\"field\":\"image[]\",\"filename\":\"image_1.png\",\"size\":125270,\"truncated\":false},{\"content_type\":\"image/png\",\"field\":\"image[]\",\"filename\":\"image_2.png\",\"size\":187278,\"truncated\":false}]},\"body_truncated\":false,\"headers\":{\"Accept\":\"\",\"Authorization\":\"Bearer sk-xxx\",\"Content-Type\":\"multipart/form-data; boundary=381f9742913725db9410bd64d6edce2b7ea96c1c8cfc8214227504c9abb8\"},\"method\":\"POST\",\"url\":\"https://ai.yalian.cloud/v1/images/edits\"},\"source\":\"upstream_do_request\"},\"use_channel\":[\"49\"]},\"channel_id\":49,\"channel_name\":\"星跃-1000RPM\",\"channel_type\":1,\"error_code\":\"do_request_failed\",\"error_type\":\"new_api_error\",\"request_path\":\"/v1/images/edits\",\"status_code\":500}',1782843619,1782843622,0);
INSERT INTO `new-api`.`logs_tmp_06`(`id`,`user_id`,`created_at`,`type`,`content`,`username`,`token_name`,`model_name`,`quota`,`prompt_tokens`,`completion_tokens`,`use_time`,`is_stream`,`channel_id`,`channel_name`,`token_id`,`group`,`ip`,`request_id`,`other`,`started_at`,`finished_at`,`timeout_cleaned`) VALUES(5542203,3,1782843619,5,'status_code=500, upstream error: do request failed','maas','maas','gpt-image-2',0,0,0,3,0,49,NULL,4,'default','','202606301820192229272888268d9d6UtHLdqyK','{\"admin_info\":{\"upstream\":{\"request\":{\"body\":{\"content_type\":\"multipart/form-data\",\"fields\":{\"model\":\"gpt-image-2\",\"prompt\":{\"truncated\":true,\"value\":\"请严格按照以下中文要求，生成 1 张可直接用于中国区游戏商店投放的 16:9 游戏宣传图片。\\n\\n目标场景：16:9 横版游戏宣传图。\\n目标：生成一张兼顾高识别主体特写与标题识别的游戏宣传图。画面需要让标题与主体特写共同构成一个完整、连贯的宣传视觉，让用户优先看清最有识别度的局部主体、关键动作和玩法瞬间，同时通过有设计感的大标题强化品牌识别。标题需要明显突出，但不能遮挡或取代主体特写与关键瞬间。\\n\\n画布：1920x1080，宽高比 16:9。\\n硬性约束：保持构图清晰，并与游戏真实风格一致。\\n\\n游戏信息：\\n- 游戏标题必须显示为「足球战术大师」。\\n- 标题共 6 个字，必须逐字准确，不得替换、改写、缺失、错字、同音字、近义字或其他变体。\\n\\n需要保留的视觉识别：\\n- 画风：极简界面UI。\\n- 情绪氛围：策略性、职业感。\\n\\n参考图要求：\\n- 当前请求附带了开发者提供的参考图，可将其作为玩法内容和视觉方向的补充锚点。\\n- 如果参考图来自实机截图、宣传图或已有素材，应优先提炼其中与真实玩法一致的主体关系、交互对象、行为线索和结果反馈，而不是只提炼表面风格。\\n- 参考图只能帮助校准真实内容、玩法关系和视觉气质，不能把画面带向脱离玩法的概念包装。\\n- 不要直接照搬原图构图、背景、装饰文字、界面排版或 UI。\\n- 若使用实机截图作为参考，只提炼其中最有代表性的玩法符号、环境色调和动作关系，不保留完整截图感和原始布局。\\n- 风格锚定：必须复刻参考图的「保持界面UI的简洁与功能性，避免写实主义插画」。背景应保持与游戏内界面一致的低复杂度，主体为游戏UI元素，细节体现在文字信息和按钮设计上。。\\n- 如果参考图带有 HUD、按钮、血条、进度条、数值、角标、卡片、小地图、操作提示或其他游戏内 UI 元素，必须主动忽略并清除；只保留去 UI 后仍然成立的玩法主体和内容关系。\\n- 宣传图只保留纯游戏内容主体、场景关系和美术气质，不保留截图式界面覆盖层，也不要把参考图中的 UI 反馈误当成最终设计元素。\\n\\n差异化方案：\\n- 构图：采用左上标题、右侧主体的对角线构图，让视线从标题自然落到关键动作。\\n- 主体位置：主体特写集中在右侧或右下，关键反馈留在标题对角区域，避免互相遮挡。\\n- 标题位置建议：左上标题区。\\n- 标题位于画面左上方的稳定标题区，整体视觉存在感约占画面 16% 到 22% 左右。\\n- 主体特写与关键瞬间主要落在画面右侧或右下方的主体特写区域，与标题位置错开，互不遮挡。\\n\\n场景要求：\\n- 这是一张游戏宣传图，不是纯标题海报，也不是完整截图直接贴字。\\n- 必须保留与游戏一致的核心玩法语义，但不要求把完整玩法流程完整铺开。\\n- 标题文字是重要的宣传识别元素，需要明显突出，但不能压制主体特写与关键瞬间，并应顺着主体动作、场景走势和整体节奏自然融入画面。\\n- 画面使用艺术设计，在保留实机语义的情况下，脱离截图重新编排场景布局，优先选择最有识别度的局部主体与关键玩法瞬间进行艺术重绘和表达，确保角色特征、核心气质、玩家体验与真实游戏一致。\\n- 标题在左上形成品牌锚点，主体动作从中部向右侧展开，标题与主体之间保留清晰呼吸感。\\n- 标题放在画面左上方的稳定标题区，主体特写与关键瞬间放在画面右侧或右下方的主体特写区域，两者位置错开，不要互相遮挡，同时要保持构图呼应，不要像后期单独贴上的独立层。\\n- 视觉还原优先级：必须确保生成的画面在美术形式上与参考图高度对齐，严格遵循「保持界面UI的简洁与功能性，避免写实主义插画」，并满足「背景应保持与游戏内界面一致的低复杂度，主体为游戏UI元素，细节体现在文字信息和按钮设计上。」，杜绝过度包装导致的货不对板。\\n- 标题需要足够大、足够宽、足够有体积感，成为稳定的品牌识别锚点。\\n- 主体特写与关键瞬间应清晰集中，不要分散成零散背景装饰。\\n- 主特写主体必须优先突出「战术面板、选择区域或应用按钮」，不能退化成抽象题材符号或泛化元素堆砌。\\n- 画面不能只是几个元素散落在背景里，必须围绕「战术面板、选择区域或应用按钮」这个明确主体和一个正在发生的关键瞬间展开，例如「选择战术或进入联赛」。\\n- 画面需要具有设计感，不能直接照搬原始截图，需要提炼其中最有识别度的局部特征进行艺术加工。\\n- 画面整体应体现“标题显著、主体清楚、瞬间明确、位置清晰、层级明确”，并让标题、主体特写与关键瞬间共同构成完整连贯的视觉整体。\\n- 标题位于画面左上侧，形成明确品牌锚点。\\n- 标题应占据较大宽度和足够厚度，具有明显存在感，但不要覆盖画面右侧或右下方的主体特写区域的主体特写。\\n- 画面右侧或右下方的主体特写区域必须呈现清晰的局部特写和关键瞬间，让人能一眼看清「战术面板、选择区域或应用按钮」的动作与结果反馈，即「战术应用或联赛开始」，并感知这款游戏的核心玩法语义，即「玩家通过选择战术、管理球队，提升战绩并在不同联赛中晋级，最终成为战术大师的策略模拟游戏。」。\\n- 画面可围绕 战术选择与应用、球队管理、联赛晋级、资源管理 中的少量关键元素展开，但必须突出一个主主体，不要把整体玩法平均铺满。\\n- 除主主体外，只可保留少量能支撑瞬间成立的次要主体，例如 中超联赛信息、球队名称与等级，不要把所有主体平均陈列。\\n- 标题不要遮挡主体动作与结果反馈。\\n- 画面中应保留少量最具代表性的局部元素，但必须经过整理，避免杂乱。\\n- 必须保留「玩家通过选择战术、管理球队，提升战绩并在不同联赛中晋级，最终成为战术大师的策略模拟游戏。」这一核心玩法语义，但不要求把整套玩法链路完整铺开。\\n- 可以保留 战术选择与应用、球队管理、联赛晋级、资源管理 等核心元素，但应优先服务于主体特写和关键瞬间，避免平均散落。\\n- 重点表现「模拟足球经理，侧重战术层面决策，无球场竞技画面。」，并通过局部特写、动作爆发和结果反馈去传达 足球战术、联赛管理 与 模拟经营、体育策略 的结合关系。\\n- 标题「足球战术大师」需要有明确的艺术化设计，字形、材质、轮廓、描边、光效或装饰细节应与游戏气质一致，并与主体特写、动作氛围和场景气质自然呼应，但必须保持清晰可读。\\n- 标题应具有 简洁、专业、力量感，可以带有 字体颜色明亮、字体排版整齐 或 可能包含足球相关简洁图形元素，但不要脱离参考图整体风格。\\n- 如果游戏本身画面较粗糙、玩法元素较简单，可以适度进行宣传图式提炼和强化，但这种强化应体现在线条的精致度和色彩的通透感上，不能脱离真实游戏的气质。\\n- 若背景来自实机内容，可适当进行弱化、简化和整理，例如压暗、降对比、降饱和、柔化、减少杂讯，让标题和主体特写都更清楚。\\n- 背景和场景元素只能辅助说明游戏内容，不能喧宾夺主，也不能弱到只剩空背景。背景应保持克制，严禁添加实机不符的内容画面。\\n\\n文字要求：\\n- 画面中除游戏标题外，不要出现其他任何文字、按钮文案、说明文案、宣传语或标签。\\n- 标题文字必须逐字准确显示为「足球战术大师」，这 6 个字不能替换、不能改写、不能写成同音字\"},\"quality\":\"medium\",\"size\":\"1536x1024\"},\"files\":[{\"content_type\":\"image/png\",\"field\":\"image[]\",\"filename\":\"image_0.png\",\"size\":125452,\"truncated\":false},{\"content_type\":\"image/png\",\"field\":\"image[]\",\"filename\":\"image_1.png\",\"size\":125270,\"truncated\":false},{\"content_type\":\"image/png\",\"field\":\"image[]\",\"filename\":\"image_2.png\",\"size\":187278,\"truncated\":false}]},\"body_truncated\":false,\"headers\":{\"Accept\":\"\",\"Authorization\":\"Bearer sk-xxx\",\"Content-Type\":\"multipart/form-data; boundary=bb38afc5aacf8c5b74fa0863e6e7987c72dea2a5ca30d44fb28d7555d0d6\"},\"method\":\"POST\",\"url\":\"https://ai.yalian.cloud/v1/images/edits\"},\"source\":\"upstream_do_request\"},\"use_channel\":[\"49\",\"49\"]},\"channel_id\":49,\"channel_name\":\"星跃-1000RPM\",\"channel_type\":1,\"error_code\":\"do_request_failed\",\"error_type\":\"new_api_error\",\"request_path\":\"/v1/images/edits\",\"status_code\":500}',1782843619,1782843625,0);
INSERT INTO `new-api`.`logs_tmp_06`(`id`,`user_id`,`created_at`,`type`,`content`,`username`,`token_name`,`model_name`,`quota`,`prompt_tokens`,`completion_tokens`,`use_time`,`is_stream`,`channel_id`,`channel_name`,`token_id`,`group`,`ip`,`request_id`,`other`,`started_at`,`finished_at`,`timeout_cleaned`) VALUES(5542204,3,1782843587,5,'status_code=500, upstream error: do request failed','maas','maas','gpt-image-2',0,0,0,3,0,49,NULL,4,'default','','20260630181947373677058268d9d6nVaQqmqB','{\"admin_info\":{\"upstream\":{\"request\":{\"body\":{\"content_type\":\"multipart/form-data\",\"fields\":{\"model\":\"gpt-image-2\",\"prompt\":\"基于参考图生成《折翼之歌》第十七集大千制药厂休息室16:9多视图场景设计板，真人电影写实风格，无人物。保持同一间旧制药厂休息室：旧水泥墙、冷白顶灯、窗外制药厂建筑、几张简易床/大通铺、床边柜、右侧桌子、医用用品、角落垃圾桶里一卷带血绷带但不血腥。设计板需要展示同一空间的3-4个角度：1）从门口看向窗边和床位；2）从窗边看向床和房间入口；3）床边近景，适合陶立躺床、魏恩瑶在床边处理；4）窗边角度，适合周进站在窗边看外面。每个角度都保持同一空间布局和道具位置，不要加入文字标签、英文、Logo、水印，不要出现人物。clean high-resolution cinema image, ultra sharp but natural, real live-action cinema frame, clean concrete wall texture, clean floor texture, clear bedding fabric texture, no noise, no grain, no low-resolution video frame, no AI sharpening artifacts, no dirty edge halos, no painterly look, no game CG。\",\"quality\":\"medium\",\"size\":\"1536x1024\"},\"files\":[{\"content_type\":\"image/png\",\"field\":\"image\",\"filename\":\"image_0.png\",\"size\":2591138,\"truncated\":false}]},\"body_truncated\":false,\"headers\":{\"Accept\":\"\",\"Authorization\":\"Bearer sk-xxx\",\"Content-Type\":\"multipart/form-data; boundary=1aff2fd0bd50e9b9466ee23884ed90e2052ebfd85224950a1727a4d026ee\"},\"method\":\"POST\",\"url\":\"https://ai.yalian.cloud/v1/images/edits\"},\"source\":\"upstream_do_request\"},\"use_channel\":[\"56\",\"49\"]},\"channel_id\":49,\"channel_name\":\"星跃-1000RPM\",\"channel_type\":1,\"error_code\":\"do_request_failed\",\"error_type\":\"new_api_error\",\"request_path\":\"/v1/images/edits\",\"status_code\":500}',1782843587,1782843650,0);
INSERT INTO `new-api`.`logs_tmp_06`(`id`,`user_id`,`created_at`,`type`,`content`,`username`,`token_name`,`model_name`,`quota`,`prompt_tokens`,`completion_tokens`,`use_time`,`is_stream`,`channel_id`,`channel_name`,`token_id`,`group`,`ip`,`request_id`,`other`,`started_at`,`finished_at`,`timeout_cleaned`) VALUES(5542206,3,1782843657,5,'status_code=500, upstream error: do request failed','maas','maas','gpt-image-2',0,0,0,3,0,49,NULL,4,'default','','202606301820577173986738268d9d6UjdsA5oK','{\"admin_info\":{\"upstream\":{\"request\":{\"body\":{\"model\":\"gpt-image-2\",\"n\":1,\"prompt\":\"横版16:9顶视图游戏地图，滩涂渔村，暗黑风、史诗风、CG风、写实风。镜头垂直俯视，画面是一座荒废阴冷的海边滩涂渔村，潮湿泥滩、浅水潮沟、破旧木屋、倾斜栈桥、废弃渔网、破船残骸、木桩和碎石分布其间。渔村内明确有“滩望层水位调节石板”：一组古老石质水位调节机关石板，嵌在滩涂与浅水之间，带有层级刻度、沟槽、符文和闸门结构，部分被海泥和盐霜覆盖，像能调节潮水水位的遗迹装置。画面一侧有破损防浪堤，堤坝由黑灰巨石、锈蚀铁桩和碎裂混凝土构成，局部坍塌，被海浪冲刷，周围有白沫、湿滑海藻和漂流残骸。整体氛围阴冷、荒凉、黑暗史诗，色调为冷灰、暗青、黑褐、锈红和浑浊沙色，电影级光影，风暴前的薄雾与低沉海潮感，细节丰富，地图可读性清晰，适合作为游戏大地图背景，无人物近景，无文字水印。\",\"quality\":\"medium\",\"size\":\"1536x1024\"},\"body_truncated\":false,\"headers\":{\"Accept\":\"\",\"Authorization\":\"Bearer sk-xxx\",\"Content-Type\":\"application/json\"},\"method\":\"POST\",\"url\":\"https://ai.yalian.cloud/v1/images/generations\"},\"source\":\"upstream_do_request\"},\"use_channel\":[\"56\",\"49\"]},\"channel_id\":49,\"channel_name\":\"星跃-1000RPM\",\"channel_type\":1,\"error_code\":\"do_request_failed\",\"error_type\":\"new_api_error\",\"request_path\":\"/v1/images/generations\",\"status_code\":500}',1782843657,1782843721,0);
INSERT INTO `new-api`.`logs_tmp_06`(`id`,`user_id`,`created_at`,`type`,`content`,`username`,`token_name`,`model_name`,`quota`,`prompt_tokens`,`completion_tokens`,`use_time`,`is_stream`,`channel_id`,`channel_name`,`token_id`,`group`,`ip`,`request_id`,`other`,`started_at`,`finished_at`,`timeout_cleaned`) VALUES(5542207,3,1782843796,5,'status_code=500, upstream error: do request failed','maas','maas','gpt-image-2',0,0,0,3,0,49,NULL,4,'default','','20260630182316172233888268d9d6F9LfawuR','{\"admin_info\":{\"upstream\":{\"request\":{\"body\":{\"content_type\":\"multipart/form-data\",\"fields\":{\"model\":\"gpt-image-2\",\"prompt\":\"《折翼之歌》第十七集17-1A高清首帧，真人电影风格，16:9。场景是大千制药厂休息室，旧水泥墙、窗外制药厂建筑、简易床铺、大通铺、床边柜、冷白顶灯，空间严格参考休息室主图和多视图。陶立躺在靠窗附近的床上，短黑发中国男性，旧蓝色牛仔工装裤、右小腿白色绷带、黑色工靴正确；上半身衣服被掀开或局部露出，腹部受伤位置正在被处理，画面克制，不做血腥特写。陶立痛得出冷汗，脸部绷紧，嘴刚要惨叫。魏恩瑶坐/站在床边，白色实验室外套、浅蓝衬衫、牛仔裤、白鞋、灰色背包或背包放在身边，马尾、眼镜正确，她正在小心清理陶立衣服碎片和凝固污渍，手部动作专业但紧张。周进站在窗边看着外面的制药厂建筑，黑色功能背心、运动背心、工装裤、黑色皮靴，侧背影或侧脸，姿态冷静。角落垃圾桶里有一卷带血绷带作为剧情道具，但不血腥。不要出现其他人物、英文、乱码、Logo、水印。clean high-resolution cinema image, ultra sharp but natural, real live-action cinema frame, natural skin texture, clear facial details, clear eyes, clear lips, clear hands and fingers, clear fabric texture, clean concrete wall texture, clean floor texture, no noise, no grain, no low-resolution video frame, no AI sharpening artifacts, no dirty edge halos, no plastic skin, no painterly look, no game CG。\",\"quality\":\"medium\",\"size\":\"1536x1024\"},\"files\":[{\"content_type\":\"image/jpeg\",\"field\":\"image[]\",\"filename\":\"image_0.jpeg\",\"size\":159148,\"truncated\":false},{\"content_type\":\"image/jpeg\",\"field\":\"image[]\",\"filename\":\"image_1.jpeg\",\"size\":209937,\"truncated\":false},{\"content_type\":\"image/jpeg\",\"field\":\"image[]\",\"filename\":\"image_2.jpeg\",\"size\":195864,\"truncated\":false},{\"content_type\":\"image/jpeg\",\"field\":\"image[]\",\"filename\":\"image_3.jpeg\",\"size\":131473,\"truncated\":false},{\"content_type\":\"image/jpeg\",\"field\"