me\":\"image_1.jpeg\",\"size\":42366,\"truncated\":false},{\"content_type\":\"image/jpeg\",\"field\":\"image[]\",\"filename\":\"image_2.jpeg\",\"size\":62522,\"truncated\":false},{\"content_type\":\"image/jpeg\",\"field\":\"image[]\",\"filename\":\"image_3.jpeg\",\"size\":70126,\"truncated\":false},{\"content_type\":\"image/jpeg\",\"field\":\"image[]\",\"filename\":\"image_4.jpeg\",\"size\":40313,\"truncated\":false},{\"content_type\":\"image/jpeg\",\"field\":\"image[]\",\"filename\":\"image_5.jpeg\",\"size\":67169,\"truncated\":false},{\"content_type\":\"image/jpeg\",\"field\":\"image[]\",\"filename\":\"image_6.jpeg\",\"size\":49060,\"truncated\":false},{\"content_type\":\"image/jpeg\",\"field\":\"image[]\",\"filename\":\"image_7.jpeg\",\"size\":46412,\"truncated\":false},{\"content_type\":\"image/jpeg\",\"field\":\"image[]\",\"filename\":\"image_8.jpeg\",\"size\":45404,\"truncated\":false},{\"content_type\":\"image/jpeg\",\"field\":\"image[]\",\"filename\":\"image_9.jpeg\",\"size\":43649,\"truncated\":false}]},\"body_truncated\":false,\"headers\":{\"Accept\":\"\",\"Authorization\":\"Bearer sk-xxx\",\"Content-Type\":\"multipart/form-data; boundary=f87e6709a93e54415b3262b0826049fe9bbef0819b3702d07a7c4fc918fb\"},\"method\":\"POST\",\"url\":\"https://ai.yalian.cloud/v1/images/edits\"},\"source\":\"upstream_do_request\"},\"use_channel\":[\"49\"]},\"channel_id\":49,\"channel_name\":\"星跃-1000RPM\",\"channel_type\":1,\"error_code\":\"do_request_failed\",\"error_type\":\"new_api_error\",\"request_path\":\"/v1/images/edits\",\"status_code\":500}',1782843834,1782843837,0);
