INSERT INTO `new-api`.`logs_tmp_06`(`id`,`user_id`,`created_at`,`type`,`content`,`username`,`token_name`,`model_name`,`quota`,`prompt_tokens`,`completion_tokens`,`use_time`,`is_stream`,`channel_id`,`channel_name`,`token_id`,`group`,`ip`,`request_id`,`other`,`started_at`,`finished_at`,`timeout_cleaned`) VALUES(5542229,3,1782844059,5,'status_code=500, upstream error: do request failed','maas','maas','gpt-image-2',0,0,0,3,0,49,NULL,4,'default','','202606301827397827968608268d9d6I6ra9vjN','{\"admin_info\":{\"upstream\":{\"request\":{\"body\":{\"model\":\"gpt-image-2\",\"n\":1,\"prompt\":\"横版16:9顶视图游戏地图，滩涂渔村，暗黑风、史诗风、CG风、写实风。镜头垂直俯视，画面是一座荒废阴冷的海边滩涂渔村，潮湿泥滩、浅水潮沟、破旧木屋、倾斜栈桥、废弃渔网、破船残骸、木桩和碎石分布其间。渔村内有众多流离渔民，以小尺度顶视图人群呈现：衣衫破旧的渔民、拖家带口的难民、围坐在临时火堆旁的人群、背着行囊的人、靠近破屋避风的人、沿泥泞小路缓慢移动的人，形成混乱但可读的避难聚落氛围；人物不做近景，只作为地图上的小型单位和生活痕迹。画面一侧有破损防浪堤，堤坝由黑灰巨石、锈蚀铁桩和碎裂混凝土构成，局部坍塌，被海浪冲刷，周围有白沫、湿滑海藻、漂流木和残骸。整体氛围阴冷、荒凉、黑暗史诗，色调为冷灰、暗青、黑褐、锈红和浑浊沙色，电影级光影，风暴前的薄雾与低沉海潮感，细节丰富，地图可读性清晰，适合作为游戏大地图背景，无文字水印。\",\"quality\":\"medium\",\"size\":\"1536x1024\"},\"body_truncated\":false,\"headers\":{\"Accept\":\"\",\"Authorization\":\"Bearer sk-xxx\",\"Content-Type\":\"application/json\"},\"method\":\"POST\",\"url\":\"https://ai.yalian.cloud/v1/images/generations\"},\"source\":\"upstream_do_request\"},\"use_channel\":[\"49\"]},\"channel_id\":49,\"channel_name\":\"星跃-1000RPM\",\"channel_type\":1,\"error_code\":\"do_request_failed\",\"error_type\":\"new_api_error\",\"request_path\":\"/v1/images/generations\",\"status_code\":500}',1782844059,1782844062,0);
INSERT INTO `new-api`.`logs_tmp_06`(`id`,`user_id`,`created_at`,`type`,`content`,`username`,`token_name`,`model_name`,`quota`,`prompt_tokens`,`completion_tokens`,`use_time`,`is_stream`,`channel_id`,`channel_name`,`token_id`,`group`,`ip`,`request_id`,`other`,`started_at`,`finished_at`,`timeout_cleaned`) VALUES(5542235,3,1782844367,5,'status_code=500, upstream error: do request failed','maas','maas','gpt-image-2',0,0,0,3,0,49,NULL,4,'default','','202606301832475082216808268d9d6pE6Rh5jR','{\"admin_info\":{\"upstream\":{\"request\":{\"body\":{\"content_type\":\"multipart/form-data\",\"fields\":{\"model\":\"gpt-image-2\",\"prompt\":\"请对原图进行编辑。编辑指令：基于原图制作《折翼之歌》EP18 FULL_REDO S12 的高清真人电影连续首帧，保持会议室夜景、徐以太已经上前挡在乔欣身前、陶立李正唐虎在座位区、背景幸存者紧张旁观，但把构图适当拉宽，让徐以太、乔欣、唐虎、李正、陶立都能清楚读出身份。剧情第0秒：徐以太上前挡在乔欣身前，怒视唐虎，准备警告“我劝你不要没事找事。”李正阴森地盯着徐以太。\\n\\n必须严格锁定清晰角色：徐以太是中年中国男性，眼镜，灰色短袖 polo 或灰色朴素上衣，挡在乔欣身前，肩膀紧绷，怒视唐虎；乔欣是年轻中国女性，浅蓝衬衫外套、米色内搭，在徐以太身后紧张担忧，不能穿白大褂，不能像魏恩瑶。唐虎是壮胖中国男性，寸头圆宽脸，深色工装，坐着或半起身看徐以太，不能带工具、绳索、电锯、武器。李正是瘦削中国男性，窄长脸，深灰旧工装，坐在陶立旁边，阴森盯着徐以太，不能穿蓝工装，不能像陶立。陶立是唯一蓝色旧牛仔工装，坐着沉默，右小腿白绷带，黑色工靴。\\n\\n空间动作：徐以太在乔欣前方形成保护姿态，唐虎在右侧座位区与他对峙，李正坐在陶立旁边阴森观察，陶立沉默坐着。背景幸存者保持普通人风格，不抢戏。不要让徐以太和唐虎距离过远；不要让乔欣跑到前面；不要让李正消失。\\n\\n表演起点：徐以太眉头压紧、下颌紧绷，嘴唇准备开口；唐虎嘴唇闭合或刚停下嘲讽，脸上不悦；李正眼神阴冷盯徐以太；乔欣担心地看徐以太；陶立沉默克制。所有清晰人物必须有自然微表情和微动作，不能呆滞无神。\\n\\n画质：clean high-resolution cinema image, ultra sharp but natural, real live-action cinema frame, natural skin texture, clear facial details, clear eyes, clear lips, clear hands and fingers, clear fabric texture, clean concrete wall texture, clean floor texture, no noise, no grain, no low-resolution video frame, no AI sharpening artifacts, no dirty edge halos, no plastic skin, no painterly look, no game CG。\\n\\n禁止：不要英文、乱码、Logo、水印、设定板文字；不要武器、工具、绳索、电锯、纸箱；不要重复角色；不要乔欣像魏恩瑶；不要裁头、裁手；不要缺肢断肢、重复条带、拼接痕迹。\",\"quality\":\"medium\",\"size\":\"1536x1024\"},\"files\":[{\"content_type\":\"image/jpeg\",\"field\":\"image[]\",\"filename\":\"image_0.jpeg\",\"size\":301657,\"truncated\":false},{\"content_type\":\"image/jpeg\",\"field\":\"image[]\",\"filename\":\"image_1.jpeg\",\"size\":42366,\"truncated\":false},{\"content_type\":\"image/jpeg\",\"field\":\"image[]\",\"filename\":\"image_2.jpeg\",\"size\":62522,\"truncated\":false},{\"content_type\":\"image/jpeg\",\"field\":\"image[]\",\"filename\":\"image_3.jpeg\",\"size\":70126,\"truncated\":false},{\"content_type\":\"image/jpeg\",\"field\":\"image[]\",\"filename\":\"image_4.jpeg\",\"size\":40313,\"truncated\":false},{\"content_type\":\"image/jpeg\",\"field\":\"image[]\",\"filename\":\"image_5.jpeg\",\"size\":67169,\"truncated\":false},{\"content_type\":\"image/jpeg\",\"field\":\"image[]\",\"filename\":\"image_6.jpeg\",\"size\":49060,\"truncated\":false},{\"content_type\":\"image/jpeg\",\"field\":\"image[]\",\"filename\":\"image_7.jpeg\",\"size\":46412,\"truncated\":false},{\"content_type\":\"image/jpeg\",\"field\":\"image[]\",\"filename\":\"image_8.jpeg\",\"size\":45404,\"truncated\":false},{\"content_type\":\"image/jpeg\",\"field\":\"image[]\",\"filename\":\"image_9.jpeg\",\"size\":43649,\"truncated\":false}]},\"body_truncated\":false,\"headers\":{\"Accept\":\"\",\"Authorization\":\"Bearer sk-xxx\",\"Content-Type\":\"multipart/form-data; boundary=cbbab7b20ef983c4c0071e0dae02f5a20370819efef1892e0f3cf7cc9a47\"},\"method\":\"POST\",\"url\":\"https://ai.yalian.cloud/v1/images/edits\"},\"source\":\"upstream_do_request\"},\"use_channel\":[\"49\",\"49\"]},\"channel_id\":49,\"channel_name\":\"星跃-1000RPM\",\"channel_type\":1,\"error_code\":\"do_request_failed\",\"error_type\":\"new_api_error\",\"request_path\":\"/v1/images/edits\",\"status_code\":500}',1782844367,1782844375,0);
