INSERT INTO `new-api`.`logs_tmp_06`(`id`,`user_id`,`created_at`,`type`,`content`,`username`,`token_name`,`model_name`,`quota`,`prompt_tokens`,`completion_tokens`,`use_time`,`is_stream`,`channel_id`,`channel_name`,`token_id`,`group`,`ip`,`request_id`,`other`,`started_at`,`finished_at`,`timeout_cleaned`) VALUES(5542406,3,1782850932,5,'status_code=500, upstream error: do request failed','maas','maas','gpt-image-2',0,0,0,3,0,49,NULL,4,'default','','202606302022122645304318268d9d6MgmRQOtC','{\"admin_info\":{\"upstream\":{\"request\":{\"body\":{\"model\":\"gpt-image-2\",\"n\":1,\"prompt\":\"横版16:9顶视图内部游戏地图，皇家藏书馆2层，暗黑风、史诗风、CG风、写实风。镜头垂直俯视，画面是一座昔日帝国皇家藏书馆的第二层，空间比一层更高、更神秘，带有环形廊桥、二层书架平台、破损栏杆、悬空档案廊、石质阶梯、塌陷楼板和深邃阴影。厚重黑灰石墙、古老拱门、黑金帝国纹路、冷灰石板地面和尘埃光束构成整体结构。大厅中分布大量高大破损书架、倒塌书柜、散落卷轴、破碎书页、石质档案台、悬浮书页、水晶记忆柱、残破阅读桌、烛台和古老机关。地图最深处明确有“原版天光契约碑文”：一座庄严古老的天光契约碑文石碑或碑墙位于二层最深处终点平台，石碑刻有天光契约符文、星光般的圣洁刻线、古老帝国契约印记和微弱冷金/苍白光芒，是地图视觉核心。碑文周围有环形石阶、破碎书页、圣光尘埃和黑暗侵蚀痕迹。整体氛围神秘、压抑、知识圣地、黑暗史诗，色调为冷灰、黑金、暗红、深褐、苍白天光，电影级光影，强烈明暗对比，细节丰富，地图可读性清晰，适合作为游戏内部关卡地图，无人物近景，无文字水印，不要出现可读文字标签。\",\"quality\":\"medium\",\"size\":\"1536x1024\"},\"body_truncated\":false,\"headers\":{\"Accept\":\"\",\"Authorization\":\"Bearer sk-xxx\",\"Content-Type\":\"application/json\"},\"method\":\"POST\",\"url\":\"https://ai.yalian.cloud/v1/images/generations\"},\"source\":\"upstream_do_request\"},\"use_channel\":[\"49\"]},\"channel_id\":49,\"channel_name\":\"星跃-1000RPM\",\"channel_type\":1,\"error_code\":\"do_request_failed\",\"error_type\":\"new_api_error\",\"request_path\":\"/v1/images/generations\",\"status_code\":500}',1782850932,1782850935,0);
INSERT INTO `new-api`.`logs_tmp_06`(`id`,`user_id`,`created_at`,`type`,`content`,`username`,`token_name`,`model_name`,`quota`,`prompt_tokens`,`completion_tokens`,`use_time`,`is_stream`,`channel_id`,`channel_name`,`token_id`,`group`,`ip`,`request_id`,`other`,`started_at`,`finished_at`,`timeout_cleaned`) VALUES(5542411,3,1782851943,5,'status_code=500, upstream error: do request failed','maas','maas','gpt-image-2',0,0,0,3,0,49,NULL,4,'default','','202606302039033500752268268d9d6TmBIcU2r','{\"admin_info\":{\"upstream\":{\"request\":{\"body\":{\"content_type\":\"multipart/form-data\",\"fields\":{\"model\":\"gpt-image-2\",\"prompt\":\"你是一位世界顶尖的独立游戏艺术总监。请基于传入的 16:9 宣传图进行 1:1 比例重构，保持核心视觉元素、构图风格、色调一致。游戏名为「卦里藏金：寻龙探墓」。\\n\\n【核心要求】\\n1. 第一张参考图是该游戏已审核通过的 16:9 宣传图（PROMO），你必须以它为主要视觉基准\\n2. 后续参考图是游戏的实际截图，仅供补充了解游戏风格\\n3. 生成的 1:1 方形图必须与 PROMO 在以下方面保持高度一致：\\n   - 核心角色 / 主体元素\\n   - 整体色调与光影氛围\\n   - 艺术风格与视觉语言\\n4. 画面中游戏名「卦里藏金：寻龙探墓」是唯一允许出现的文本元素\\n5. 如果原 PROMO 中有任何中文文字，要想办法消除掉\\n6. 合理适配 1:1 构图——可以裁切或重新编排元素位置，但不能丢失核心主体\",\"quality\":\"medium\",\"size\":\"1024x1024\"},\"files\":[{\"content_type\":\"image/jpeg\",\"field\":\"image[]\",\"filename\":\"image_0.jpeg\",\"size\":314674,\"truncated\":false},{\"content_type\":\"image/jpeg\",\"field\":\"image[]\",\"filename\":\"image_1.jpeg\",\"size\":314674,\"truncated\":false},{\"content_type\":\"image/png\",\"field\":\"image[]\",\"filename\":\"image_2.png\",\"size\":1919990,\"truncated\":false},{\"content_type\":\"image/png\",\"field\":\"image[]\",\"filename\":\"image_3.png\",\"size\":2031720,\"truncated\":false},{\"content_type\":\"image/png\",\"field\":\"image[]\",\"filename\":\"image_4.png\",\"size\":2699605,\"truncated\":false}]},\"body_truncated\":false,\"headers\":{\"Accept\":\"\",\"Authorization\":\"Bearer sk-xxx\",\"Content-Type\":\"multipart/form-data; boundary=4bae0cfe0c9858185a72d3240927a019a6f9719c400d0d2d08bd9c360920\"},\"method\":\"POST\",\"url\":\"https://ai.yalian.cloud/v1/images/edits\"},\"source\":\"upstream_do_request\"},\"use_channel\":[\"49\"]},\"channel_id\":49,\"channel_name\":\"星跃-1000RPM\",\"channel_type\":1,\"error_code\":\"do_request_failed\",\"error_type\":\"new_api_error\",\"request_path\":\"/v1/images/edits\",\"status_code\":500}',1782851943,1782851947,0);
INSERT INTO `new-api`.`logs_tmp_06`(`id`,`user_id`,`created_at`,`type`,`content`,`username`,`token_name`,`model_name`,`quota`,`prompt_tokens`,`completion_tokens`,`use_time`,`is_stream`,`channel_id`,`channel_name`,`token_id`,`group`,`ip`,`request_id`,`other`,`started_at`,`finished_at`,`timeout_cleaned`) VALUES(5542413,3,1782852006,5,'status_code=500, upstream error: do request failed','maas','maas','gpt-image-2',0,0,0,3,0,49,NULL,4,'default','','202606302040062260385898268d9d6FDsXRb3m','{\"admin_info\":{\"upstream\":{\"request\":{\"body\":{\"model\":\"gpt-image-2\",\"n\":1,\"prompt\":\"横版16:9顶视图地下游戏地图，皇家地宫二层，暗黑风、史诗风、CG风、写实风。镜头垂直俯视，画面是帝国王室地下地宫第二层，比一层更深、更阴冷、更复杂。地图明确包含入口：从上一层下来的入口位于地图一侧或上方区域，是向下阶梯、升降井出口或沉重石门，带有王室纹章和冷金符文。入口后是地宫前厅石壁：一片宽阔前厅，厚重黑灰石壁、巨大浮雕墙、王室墓志纹样、裂开的石碑壁面、熄灭火盆和阴影墙龛，形成压迫感。地图包含错综复杂的道路：多条地下石道、交叉走廊、回环通路、狭窄岔路、断桥、封闭墓道和隐藏侧道互相连接，形成迷宫般但可读的二层地宫结构。地图还明确有下一层的入口：位于最深处或远端核心区域，是通往更深层的黑暗阶梯、封印圆井、地下石门或暗红发光竖井，周围有王室封印、暗红光、冷金符文和石棺守卫结构。场景中有王室陵寝石棺、破碎雕像、残破火盆、锈蚀铁门、古老机关、地下积水、青苔、塌落碎石和阴冷雾气。整体色调为冷灰、黑金、暗红、深褐、苍白幽光，电影级光影，强烈明暗对比，细节丰富，地图可读性清晰，适合作为地下关卡地图背景，无人物近景，无文字水印，不要出现可读文字标签。\",\"quality\":\"medium\",\"size\":\"1536x1024\"},\"body_truncated\":false,\"headers\":{\"Accept\":\"\",\"Authorization\":\"Bearer sk-xxx\",\"Content-Type\":\"application/json\"},\"method\":\"POST\",\"url\":\"https://ai.yalian.cloud/v1/images/generations\"},\"source\":\"upstream_do_request\"},\"use_channel\":[\"49\"]},\"channel_id\":49,\"channel_name\":\"星跃-1000RPM\",\"channel_type\":1,\"error_code\":\"do_request_failed\",\"error_type\":\"new_api_error\",\"request_path\":\"/v1/images/generations\",\"status_code\":500}',1782852006,1782852009,0);
