INSERT INTO `new-api`.`logs_tmp_06`(`id`,`user_id`,`created_at`,`type`,`content`,`username`,`token_name`,`model_name`,`quota`,`prompt_tokens`,`completion_tokens`,`use_time`,`is_stream`,`channel_id`,`channel_name`,`token_id`,`group`,`ip`,`request_id`,`other`,`started_at`,`finished_at`,`timeout_cleaned`) VALUES(5542452,3,1782856797,5,'status_code=500, upstream error: do request failed','maas','maas','gpt-image-2',0,0,0,3,0,49,NULL,4,'default','','20260630215957622337658268d9d6e4Agnc41','{\"admin_info\":{\"upstream\":{\"request\":{\"body\":{\"model\":\"gpt-image-2\",\"n\":1,\"prompt\":\"横版16:9顶视图地下洞窟游戏地图，浊光洞窟，暗黑风、史诗风、CG风、写实风。镜头垂直俯视，画面是一座被污浊圣光与地底浊气侵蚀的巨大地下洞窟。地图包含洞窟核心区域：中央开阔洞厅，岩壁环绕，布满钟乳石、断裂石柱、黑色矿脉、暗金光垢晶体和潮湿岩面，地面有裂缝、碎石、腐化符文路径和幽暗雾气。地图明确包含洞窟核心：位于核心区域中央或深处的巨大浊光晶核/腐化圣光核心，像污浊白金色水晶与黑暗肉质矿石融合，散发冷金与暗青光芒，并向四周蔓延污染裂纹。地图明确包含洞窟祭坛：一座古老石质祭坛位于核心附近或侧翼平台上，祭坛有黑灰石台、环形符文、破碎献祭器皿、残破石柱、冷金光线和暗红痕迹。地图明确包含地底浊气池：一片或数片浑浊发光的地下池水，呈暗青、污白、黑紫色，表面冒泡、散发毒雾和微光，池边有腐化结晶、石阶和裂开的岩层。整体色调为冷灰、黑金、暗青、污白、暗紫、深褐，电影级光影，强烈明暗对比，水雾与浊气弥漫，细节丰富，地图可读性清晰，适合作为地下洞窟关卡地图背景，无人物近景，无文字水印，不要出现可读文字标签。\",\"quality\":\"medium\",\"size\":\"1536x1024\"},\"body_truncated\":false,\"headers\":{\"Accept\":\"\",\"Authorization\":\"Bearer sk-xxx\",\"Content-Type\":\"application/json\"},\"method\":\"POST\",\"url\":\"https://ai.yalian.cloud/v1/images/generations\"},\"source\":\"upstream_do_request\"},\"use_channel\":[\"49\",\"49\"]},\"channel_id\":49,\"channel_name\":\"星跃-1000RPM\",\"channel_type\":1,\"error_code\":\"do_request_failed\",\"error_type\":\"new_api_error\",\"request_path\":\"/v1/images/generations\",\"status_code\":500}',1782856797,1782856804,0);
