INSERT INTO `new-api`.`logs_tmp_06`(`id`,`user_id`,`created_at`,`type`,`content`,`username`,`token_name`,`model_name`,`quota`,`prompt_tokens`,`completion_tokens`,`use_time`,`is_stream`,`channel_id`,`channel_name`,`token_id`,`group`,`ip`,`request_id`,`other`,`started_at`,`finished_at`,`timeout_cleaned`) VALUES(5542520,3,1782862595,5,'status_code=500, upstream error: do request failed','maas','maas','gpt-image-2',0,0,0,3,0,49,NULL,4,'default','','202606302336359647207148268d9d6C7XBhwJC','{\"admin_info\":{\"upstream\":{\"request\":{\"body\":{\"model\":\"gpt-image-2\",\"n\":1,\"prompt\":\"专业科技竖版信息图海报，标题为\\\"Agency Agents · 一人一公司，232个AI专家\\\"\\n深色科技风格，竖版布局（9:16），分为以下6个区域。所有文字必须是中文，清晰可读，不拥挤：\\n\\n【顶部装饰质感横幅 · 科技感标题区】占比12%\\n- 深蓝黑(#090a15)背景，纵向渐变从左下到右上\\n- 右上角：大面积青蓝色发光光晕（#00d4ff→#4f8cff渐变），半圆形扩散，边缘柔和羽化\\n- 左上角：抽象科技几何线条/网格纹理，微弱发光，线条干净利落\\n- 磨砂玻璃纹理，光点粒子散布\\n- 底部极细发光分割线过渡\\n\\n【主标题区】占比10%\\n- 超大号粗体\\\"Agency Agents · 一人一公司\\\"，横向渐变发光 #00d4ff→#4f8cff→#a78bfa\\n- 正下方冰蓝色 \\\"#232个AI专家\\\" 大字，轻微外发光\\n- 最下方小字\\\"msitarzewski/agency-agents · MIT开源\\\"，灰色\\n- 所有文字在黑幕布上极其醒目，像霓虹灯管在黑夜里\\n\\n【核心定位+6大业务线区】占比38%\\n顶部：一张暗色磨砂玻璃卡，居中展示核心定位：\\n- 左侧标签条「📌 一句话定位」电光青色\\n- 正文：「232个深度专业化的AI特工，覆盖6大业务线——你不是一个人在战斗。」\\n\\n下方：6大业务线，每行3条，两条水平带，每种视觉形式不同：\\n\\n上排：\\n\\n① 产品研发线 55 — 横向4列展示卡\\n4张平行小卡横排，卡片深色半透明玻璃质感+电光青发光边框\\n每卡显示：岗位名+亮点标签\\n岗位1「前端/后端/AI工程师」→ 标签「飞书集成」\\n岗位2「UI/UX设计师」→ 标签「全链路」\\n岗位3「自动化测试/QA」→ 标签「质量把关」\\n岗位4「产品经理/Sprint规划」→ 标签「0到1决策」\\n\\n② 市场增长线 43 — 2×2栅格矩阵\\n四个象限小卡片，琥珀色边框，每个显示一个方向\\n左上「🇨🇳 中国全平台」→ 小红书/公众号/B站/知乎\\n右上「🌍 海外社媒」→ Twitter/TikTok/Instagram\\n左下「🔍 SEO+内容」→ 搜索+内容双驱动\\n右下「💰 付费流量操盘」→ PPC/程序化投放/社交广告\\n\\n③ 销售客服线 15 — 竖排陈列柜\\n垂直3行，紧凑清晰\\n行1「外展策略师 → 从获客到签约」\\n行2「管道分析师 → 复购+续费管理」\\n行3「客服/合规/高管摘要 → 售后闭环」\\n边框为冰蓝色，轻薄\\n\\n下排：\\n\\n④ 运营风控线 20+ — 标签药丸清单\\n水平排列的圆角发光标签，紫色边框\\n标签1「🔐 渗透测试」标签2「☁️ 云安全」标签3「📊 财务分析」标签4「🔍 投资研究」标签5「📋 合规审计」\\n\\n⑤ 垂直行业线 66+（🔥最大部门）— 公告牌/瀑布流\\n三列全宽展示，暖金色边框，标注「🔥 最大部门·53个特化岗位」\\n列1「医疗编码/法务顾问/房地产」\\n列2「HR招聘/供应链/采购」\\n列3「GIS数字孪生/MCP构建器/Salesforce架构」\\n\\n⑥ 创新战略线 33 — 图标画廊\\n水平排列小图标式模块，紫蓝色边框\\n模块1「🎮 游戏开发」→ Unity/Unreal/Godot\\n模块2「🕶️ 空间计算」→ Vision Pro/XR/Metal 3D\\n模块3「🧠 商业策略」→ 策略师/变革管理/参谋长\\n\\n【三大实战场景区】占比16%\\n标题「三大实战场景」电光青大字\\n三张带色标的大卡横向并排，每张卡片底部有一句话结论（粗体发光）\\n\\n卡片1（电光青边框）：💼 外包项目交付\\n箭头流程图：PM立项→UX调研→前端+后端开发→测试→DevOps上线\\n底部：6个AI角色串起全流程，单人交付\\n\\n卡片2（暖金边框）：📱 个人IP矩阵\\n平台icon链条：小红书→公众号→B站→Twitter→数据分析\\n底部：一个账号运营全平台，内容矩阵自动流转\\n\\n卡片3（紫蓝边框）：🏢 投资人会议\\n阶梯流程：CFO财务→投资研究员估值→策略师方向→高管摘要→演讲稿\\n底部：一个人顶一整支FA团队\\n\\n【三步上手区】占比14%\\n标题「三步上手」电光青色\\n水平三步流程图，用发光箭头串联：\\n三个圆角发光卡片（电光青边框）：\\n卡片1「① 浏览选人」→ 从232个特工中找到你需要的专家\\n卡片2「② 加载激活」→ 在你的AI工具中调出该特工角色\\n卡片3「③ 委派交付」→ 把任务交给它，写代码/拟文案/做分析\\n\\n下方：🔌 Hermes专属高亮框（暖金色边框）\\n「Hermes用户走延迟加载插件，无需安装232个技能。搜→看→载→派，4个工具搞定。」\\n\\n【底部收尾区】占比6%\\n- 发光分割线\\n- 暖金大字居中：「你是CEO，AI是你的团队」\\n- 冰蓝小字：Agency Agents · 一人一公司 · 116K Stars\\n- 底部无署名，干净收尾\\n\\n【整体配色与质感要求】\\n- 背景色：深蓝黑 #0a0e27，深邃渐变\\n- 主色调：青蓝渐变 #00d4ff→#4f8cff，强烈发光，霓虹灯管效果\\n- 辅助色：琥珀 #ffa726、紫色 #a78bfa、冰蓝 #7EC8E3、暖金 #FFD700\\n- 所有文字高亮发光，在黑底上极其清晰\\n- 卡片材质：磨砂玻璃拟态（半透明深色背景+发光边框+内部轻微光晕）\\n- 信息密集但布局清晰、层次分明，6大业务线形式各不相同\\n- 高质量渲染，像专业科技杂志封面\\n- 底部无署名\\n- 所有文字必须是中文，清晰可读\",\"quality\":\"auto\",\"size\":\"1080x1920\"},\"body_truncated\":false,\"headers\":{\"Accept\":\"\",\"Authorization\":\"Bearer sk-xxx\",\"Content-Type\":\"application/json\"},\"method\":\"POST\",\"url\":\"https://ai.yalian.cloud/v1/images/generations\"},\"source\":\"upstream_do_request\"},\"use_channel\":[\"49\"]},\"channel_id\":49,\"channel_name\":\"星跃-1000RPM\",\"channel_type\":1,\"error_code\":\"do_request_failed\",\"error_type\":\"new_api_error\",\"request_path\":\"/v1/images/generations\",\"status_code\":500}',1782862595,1782862599,0);
