xxx\",\"Content-Type\":\"application/json\"},\"method\":\"POST\",\"url\":\"https://ai.yalian.cloud/v1/images/generations\"},\"source\":\"upstream_do_request\"},\"use_channel\":[\"49\"]},\"channel_id\":49,\"channel_name\":\"星跃-1000RPM\",\"channel_type\":1,\"error_code\":\"do_request_failed\",\"error_type\":\"new_api_error\",\"request_path\":\"/v1/images/generations\",\"status_code\":500}',1782862625,1782862628,0);
